SPECS.nbflats = { name:"New Build Flats", region:"England",
 cats:["Planning","General Notes","Building Height & Applicable Regime","Site Preparation & Contaminants","Structure","Foundations","Ground Floors","External Walls","Separating Walls","Separating Floors","Internal Walls","Works Within Flats","Roofs","Additional Notes for Walls & Roofs","Common Areas & Escape Stairs","Means of Escape & Fire Regs","Sound Insulation (Part E)","Windows, Doors & Glazing","Ventilation","Overheating (Part O)","Condensation (C2)","Drainage & Refuse","Water & Sanitary (Part G)","Services","Access (Part M)","Security (Part Q)","EV Charging & Broadband (Parts S & R)","Conservation of Fuel & Power","Extra Notes & External Works","Renewable Energy"],
 buildups:[
  {g:"FD", c:"Foundations", t:"Trench Fill Foundation", u:"Wall + 300 wide, 1000 deep",
   tgt:"To Approved Document A Section 2E and BS 8004:2015 (+A1:2020) — width from Table 10 for the load and subsoil, or the structural engineer's design",
   p:[
    "Mass concrete trench fill foundation not less than 750mm thick, of a width not less than the thickness of the wall plus 300mm and in no case less than 450mm, taken to not less than 1000mm below finished ground level and cast against undisturbed ground in a trench excavated to the full width. Concrete to BS EN 206:2013 (+A2:2021) and BS 8500-2.",
    "Foundations supporting internal loadbearing walls to be taken to not less than 600mm below finished ground level. Foundations are to be taken below the invert of any adjacent drain and are not to undermine it. Sulfate-resisting cement, or the BS 8500 design chemical class given by the ground investigation, to be used where the ground or the groundwater requires it.",
    "Where the ground falls the foundation is to be stepped. No step is to exceed the thickness of the foundation, and the higher foundation is to overlap the lower by not less than twice the height of the step, the thickness of the foundation, or 300mm, whichever is the greater — not less than 1m where the foundation is trench fill. Masonry below ground to be stepped to suit.",
    "All work in accordance with Requirement A1/2 of the Building Regulations 2010 (as amended) and BS 8004:2015 (+A1:2020) Code of Practice for Foundations. The depth and the size of the foundation are to be approved on site by the Building Control Officer to suit the conditions found in the excavation.",
    "NOTE — The width is to be confirmed against Table 10 of Approved Document A for the wall load and the subsoil, or against the structural engineer's design. Where the wall is thin, the wall thickness plus 300mm can fall below the 450mm minimum for trench fill; the 450mm governs.",
    "NOTE — Where adverse soil conditions, a change of soil type, made ground, soft spots or major tree roots are found in the excavation, work is to stop, building control is to be notified and the structural engineer's advice obtained before any concrete is placed."
   ]},
  {g:"FD", c:"Foundations", t:"Strip Foundation", u:"Wall + 300 × 225, 1000 deep",
   tgt:"To Approved Document A Table 10 and Section 2E — thickness not less than the projection each side and not less than 225mm",
   p:[
    "Concrete strip foundation with the width taken from Table 10 of Approved Document A for the wall load and the subsoil, not less than the thickness of the wall plus 300mm, and the thickness of the concrete not less than the projection of the foundation beyond each face of the wall and in no case less than 225mm. Concrete to BS EN 206:2013 (+A2:2021) and BS 8500-2, cast on undisturbed ground and taken to not less than 1000mm below finished ground level.",
    "Foundations supporting internal loadbearing walls to be taken to not less than 600mm below finished ground level. Foundations are to be taken below the invert of any adjacent drain and are not to undermine it. Sulfate-resisting cement, or the BS 8500 design chemical class given by the ground investigation, to be used where the ground or the groundwater requires it.",
    "Where the ground falls the foundation is to be stepped. No step is to exceed the thickness of the foundation, and the higher foundation is to overlap the lower by not less than twice the height of the step, the thickness of the foundation, or 300mm, whichever is the greater — not less than 1m where the foundation is trench fill. Masonry below ground to be stepped to suit.",
    "All work in accordance with Requirement A1/2 of the Building Regulations 2010 (as amended) and BS 8004:2015 (+A1:2020) Code of Practice for Foundations. The depth and the size of the foundation are to be approved on site by the Building Control Officer to suit the conditions found in the excavation.",
    "NOTE — The width is to be confirmed against Table 10 for the wall load and the subsoil, or against the structural engineer's design.",
    "NOTE — Where adverse soil conditions, a change of soil type, made ground, soft spots or major tree roots are found in the excavation, work is to stop, building control is to be notified and the structural engineer's advice obtained before any concrete is placed."
   ]},
  {g:"EW", c:"External Walls", t:"Full Fill Cavity Wall", u:"0.16 W/m²K",
   tgt:"To achieve a maximum U-value of 0.18 W/m²K, being the notional value in Approved Document L Volume 1 Table 1.1, confirmed by the SAP assessment for each flat", mf:{"k":"wall","lim":0.18,"p":{"outer":"brick","cavity":100,"fill":"full","insulation":"k106","thickness":100,"inner":"a011","mortar":"gp","finish":"pbdabs","ties":"ss45x90","gapLevel":1},"s":[{"r":"cavfull","f":"100mm Kingspan Kooltherm K106 Cavity Board (thermal conductivity 0.019 W/mK)"}]}, p:[
    "External cavity wall of 103mm facing brick outer leaf, a 100mm cavity fully filled with 100mm Kingspan Kooltherm K106 Cavity Board (thermal conductivity 0.019 W/mK), and a 100mm aircrete inner leaf of 0.11 W/mK thermal conductivity with the strength grade to the structural engineer's design, finished internally with 12.5mm plasterboard on dabs with a continuous adhesive ribbon at every perimeter, opening and service position. Stainless steel wall ties to BS EN 845-1 at 450mm vertical and 900mm horizontal centres, staggered, and at not more than 300mm vertical centres within 225mm of jambs, unbonded edges and movement joints (PD 6697).",
    "Where the building has a storey more than 11m above ground the insulation and every other component of the external wall other than those exempted in Regulation 7(3) is to achieve European Class A2-s1, d0 or A1, and the phenolic board in this build-up is to be replaced with a mineral wool full fill cavity batt of 0.034 W/mK at 150mm in a 150mm cavity, which calculates at 0.19 W/m²K and needs the SAP to be re-run, or 175mm which calculates at 0.16. See the Building Height note.",
    "This build-up calculates at 0.16 W/m²K to BS EN ISO 6946 allowing for mortar joints, wall ties and an air-gap correction of 0.01."]},
  {g:"EW", c:"External Walls", t:"Light Steel Frame Infill Wall with Brick Outer Leaf", u:"0.17 W/m²K",
   tgt:"To achieve a maximum U-value of 0.18 W/m²K, confirmed by the SAP assessment",
   p:[
    "Where the structure is a concrete or steel frame, external infill walls of 103mm facing brick supported on the slab edge or on stainless steel brick support angles at each floor, tied to the frame with stainless steel channel ties, a 50mm clear cavity, 100mm mineral wool of 0.034 W/mK (A1) fixed to the sheathing board, a breather membrane, 12mm cement particle or calcium silicate sheathing board, 150mm light gauge steel C studs at 600mm centres to the frame designer's design with 150mm mineral wool of 0.035 W/mK between the studs, a vapour control layer, and two layers of 12.5mm plasterboard.",
    "Cavity barriers at each floor level at the slab edge, around openings and at the junction with separating walls, all Class A1 or A2-s1, d0. The insulation between the steel studs is heavily bridged by the steel and the calculation is to be by the manufacturer's numerical method to BS EN ISO 10211; the figure quoted assumes 100mm of continuous external insulation over the sheathing, which is what achieves the U-value, and is to be confirmed for the actual frame layout."]},
  {g:"EW", c:"External Walls", t:"Timber Frame External Wall (Buildings with No Storey Above 11m)", u:"0.16 W/m²K",
   tgt:"To achieve a maximum U-value of 0.18 W/m²K, confirmed by the SAP assessment; timber frame is not to be used where any storey is more than 18m above ground and is to be reviewed with the fire strategy above 11m", mf:{"k":"frame","lim":0.18,"p":{"insulation":"k112","thickness":140,"studWidth":38,"studDepth":140,"spacing":400,"sheathing":"osb9","lining":"k118_375","void":0,"gapLevel":1},"s":[{"r":"frame","f":"140mm Kingspan Kooltherm K112 Framing Board (thermal conductivity 0.019 W/mK)"},{"r":"lining","f":"37.5mm Kingspan Kooltherm K118 insulated plasterboard"}]}, p:[
    "Platform timber frame external wall of 103mm brick outer leaf on stainless steel flexible ties at 600mm horizontal and 375mm vertical centres, a 50mm drained and vented cavity, breather membrane, 9mm OSB3 sheathing, 140mm x 38mm C16 studs at 400mm centres to the frame designer's design with the full stud depth filled with 140mm Kingspan Kooltherm K112 Framing Board (thermal conductivity 0.019 W/mK), a vapour control layer, and 37.5mm Kingspan Kooltherm K118 insulated plasterboard with joints taped, with any service void formed on the room side of that board rather than behind it; render on carrier board, tile hanging or cladding may replace the brick outer leaf on the upper storeys with the cladding classified as Approved Document B requires. This build-up calculates at 0.16 W/m²K to BS EN ISO 6946 by the combined method, allowing for the studs bridging the insulation at 9.5% of the area at 400mm centres and an air-gap correction of 0.01; with 12.5mm plasterboard alone it calculates at 0.20.",
    "Cavity barriers of mineral wool in a polythene sleeve or proprietary barriers at every floor level, at the line of every compartment wall and floor, around openings and at the head of the wall, so that the timber frame cavity cannot carry fire between flats; the frame is to be fire protected to give the compartment period (normally 60 minutes) by the plasterboard lining specified by the frame designer's fire test data, and the separating walls between flats are to be the twin-frame build-up carried through the frame with no continuous timber across the line. The sole plate on a damp proof course at 150mm above ground and the frame differential movement allowed for at every window head and at the eaves.",
    "NOTE — Timber frame is permitted by the Regulations at any height below 18m, but insurers, warranty providers and some building control bodies apply their own limits from four storeys, and the Structural Timber Association's fire safety during construction guidance applies on site. Confirm the acceptability with the warranty provider before the frame is designed."]},
  {g:"SW", c:"Separating Walls", t:"Separating Wall Between Flats — Cavity Masonry", u:"45 dB / REI 60",
   tgt:"To achieve airborne sound insulation of not less than 45 dB DnT,w + Ctr and 60 minutes fire resistance as a compartment wall",
   p:[
    "Separating wall between flats of two leaves of 100mm dense aggregate or aircrete blockwork of the density required by the chosen Robust Detail or the pre-completion test design, a 75mm minimum cavity with type A butterfly ties only, a parge coat or render to the cavity face where the detail requires it, the cavity fully filled with mineral wool and effectively edge sealed at the external wall and the roof so the wall is entered in SAP at a U-value of zero, and 12.5mm plasterboard on dabs to each face with a continuous perimeter ribbon (or 13mm plaster where the Robust Detail requires a wet finish). The wall is to be carried through every floor and up to the underside of the roof covering, fire stopped at the roof and at each floor junction, and no service is to be chased into it back to back.",
    "The cavity is to be closed at the external wall with a flexible cavity closer so that the external wall cavity does not connect the two flats, and the external wall inner leaf is to be of the mass the detail requires within 700mm of the separating wall. The wall is a compartment wall and every junction with the external wall, the floors and the roof is to be fire stopped for 60 minutes with the fire stopping recorded in the fire safety information.",
    "Where the wall is built to a Robust Detail, the plots are to be registered with Robust Details Ltd before work begins; otherwise pre-completion testing on one set of tests per ten flats of each construction type is required.",
    "Piped services are not to pass through the separating wall except where unavoidable, and then each pipe is enclosed for its full height in a duct or boxing lined on both faces as Approved Document E describes, the space around the pipe fire stopped and sealed on both sides with a flexible sealant, and no socket, switch or recess cut back to back with one on the other side; soil stacks and rising mains are to be kept off the separating wall wherever the layout allows."]},
  {g:"SW", c:"Separating Walls", t:"Wall Between a Flat and a Common Corridor or Stair", u:"45 dB / REI 60",
   tgt:"To achieve airborne sound insulation of not less than 45 dB DnT,w + Ctr and 60 minutes fire resistance, or 30 minutes where the building has no storey more than 5m above ground",
   p:[
    "Wall between a flat and the common escape route of 215mm dense blockwork or two leaves of 100mm blockwork as the separating wall build-up, plastered or lined with plasterboard on dabs, with the flat entrance doorset a FD30S fire door with intumescent strips, cold smoke seals and a self-closing device, tested as a complete doorset to BS 476-22 or BS EN 1634-1 and, where the building has a storey more than 11m above ground, carrying the third-party certification and the identification mark required by Regulation 7 and the Fire Safety (England) Regulations.",
    "Letter plates and services through the wall are to be fire stopped or fitted with certificated fire-rated products. A flat entrance door is a critical item: the frame, door, glazing, hardware and closer are to be the tested combination and the manufacturer's installation instructions followed."]},
  {g:"SF", c:"Separating Floors", t:"Separating Floor — Precast Concrete Plank with Screed and Resilient Layer", u:"45 / 62 dB / REI 60",
   tgt:"Airborne not less than 45 dB DnT,w + Ctr; impact not more than 62 dB L'nT,w; 60 minutes fire resistance as a compartment floor",
   p:[
    "Separating floor of 150mm minimum precast prestressed hollowcore or solid concrete planks to the manufacturer's design with a 50mm minimum structural topping where the design requires it, a resilient layer of 10mm or more closed-cell foam or mineral wool board to the Robust Detail or tested system with the edges turned up at every wall to isolate the screed, a 65mm minimum sand and cement screed or a proprietary screed, and floor finishes. Ceiling below of 12.5mm plasterboard on a metal furring system with 100mm mineral wool in the void, or a direct soffit finish where the detail permits it.",
    "The total mass of the floor excluding the ceiling is to be not less than the detail requires (typically 365 kg/m² including the screed), and the resilient layer is not to be bridged by the screed, skirtings, pipes or door thresholds. Service penetrations are to be sleeved and fire stopped for 60 minutes with the pipe materials and fire collars as Approved Document B Volume 1 Section 9.",
    "NOTE — Impact sound is the usual failure on flats. A resilient layer that is bridged at one skirting will fail the test for the whole room; the resilient edge strip is to be inspected before the screed is poured and photographed for the record."]},
  {g:"SF", c:"Separating Floors", t:"Separating Floor — Beam and Block with Resilient Layer and Screed", u:"45 / 62 dB / REI 60",
   tgt:"Airborne not less than 45 dB DnT,w + Ctr; impact not more than 62 dB L'nT,w; 60 minutes fire resistance as a compartment floor",
   p:[
    "Separating floor of 150mm or 225mm precast prestressed concrete beams with dense aggregate infill blocks to the manufacturer's design, grouted and brushed with a sand and cement slurry to seal every joint, a 50mm structural or levelling screed where the detail requires it, a resilient layer of closed-cell foam or mineral wool board to the Robust Detail with the edges turned up at every wall, a 65mm minimum sand and cement screed with mesh, and floor finishes. Ceiling below of 12.5mm plasterboard on a metal furring system or timber battens with 100mm mineral wool in the void, or a direct plaster finish where the tested detail permits it.",
    "The mass of the beam and block deck with its screed is to be not less than the detail requires (typically 365 kg/m² including the screed); infill blocks are to be dense aggregate, not aircrete, unless the detail is tested with them; every service hole through the deck is to be made good in full and fire stopped for 60 minutes; and the resilient layer is not to be bridged at skirtings, thresholds or pipes.",
    "NOTE — Beam and block is the most economical concrete separating floor for a small block but the joints between blocks are its weakness for airborne sound and fire; the slurry seal and the screed are not optional."]},
  {g:"SW", c:"Separating Walls", t:"Separating Wall Between Flats — Twin Metal or Timber Frame", u:"45 dB / REI 60",
   tgt:"To achieve airborne sound insulation of not less than 45 dB DnT,w + Ctr and the compartment period of fire resistance",
   p:[
    "Where the structure is framed, the separating wall between flats is to be two independent frames of 70mm or 90mm metal C studs, or 89mm x 38mm timber studs, each with its own head and base track and no rigid connection between them, a 240mm minimum overall thickness with a 50mm minimum gap between the frames, 60mm minimum mineral wool of 10 kg/m³ or more in each frame or the cavity, and two layers of 12.5mm plasterboard of not less than 22 kg/m² total on each face (three layers where the tested detail requires them for 60 minutes), joints staggered and every perimeter sealed with acoustic sealant. Built to a registered Robust Detail or a system with a UKAS-tested certificate for both sound and fire.",
    "The wall is to be carried through the floor zone with the floor deck stopped each side of the wall and the void fire stopped and filled with mineral wool, and through the roof void to the underside of the roof covering; sockets are to be offset and boxed, no service is to pass through the wall other than in a tested fire-stopped detail, and the external wall inner lining is to be broken at the separating wall with a flexible cavity barrier so that flanking is controlled. Where the frame is steel the studs are to be isolated from the floor with a resilient strip."]},
  {g:"SF", c:"Separating Floors", t:"Separating Floor — Timber or Metal Web Joists with Platform Floor", u:"45 / 62 dB / REI 60",
   tgt:"Airborne not less than 45 dB DnT,w + Ctr; impact not more than 62 dB L'nT,w; fire resistance 60 minutes (30 minutes where the top storey is not more than 5m above ground)",
   p:[
    "Separating floor of 47mm x 220mm minimum solid or engineered joists at 400mm or 600mm centres to the designer's specification, 18mm tongued and grooved OSB3 or plywood deck, a platform floor of 19mm gypsum-based board and 18mm tongued and grooved chipboard on a resilient layer of 25mm mineral wool board or more, or a proprietary resilient batten system, isolated from all walls by a flanking strip, 100mm mineral wool of 10 kg/m³ or more in the joist void, and a ceiling of two layers of plasterboard of total mass not less than 20 kg/m² on resilient bars fixed across the joists, all as a registered Robust Detail or a tested system.",
    "For 60 minutes fire resistance the ceiling is to be the tested two-layer system with the joints staggered and the resilient bars at the tested centres, and downlighters are not to be installed in the separating ceiling. The floor is only to be used where the building height and the fire strategy permit a timber compartment floor; where the building has a storey more than 11m above ground a concrete floor is to be used.",
    "NOTE — Timber separating floors rely on every layer being present and unbridged. Where the finishes contractor is separate from the main contractor, the platform floor and flanking strips are to be inspected before the finishes are laid."]},
  {g:"IW", c:"Internal Walls", t:"Internal Partition Within a Flat", u:"40 dB Rw",
   tgt:"To achieve a laboratory sound reduction of not less than 40 dB Rw between a bedroom or a room containing a WC and other rooms (Requirement E2)",
   p:[
    "Internal partition within a flat of 70mm or 92mm metal C studs or 89mm x 38mm timber studs at 400mm or 600mm centres, the stud depth filled with 50mm minimum mineral wool of 10 kg/m³ or more, and 12.5mm plasterboard of not less than 10 kg/m² each side with joints staggered, taped and filled and all perimeters sealed. Partitions to the ceiling soffit or to the underside of the suspended ceiling with the head detail sealed. Where a partition separates a bedroom from a room with a WC, or divides a habitable room from a bathroom, the specification is not to be reduced.",
    "Where an internal partition is also part of the fire enclosure of a protected entrance hall within a flat, it is to give 30 minutes fire resistance and the doors to habitable rooms off the hall are to be FD30S fire doorsets (E 30 Sa, with intumescent strips and cold smoke seals) fitted with a self-closing device, adopted as the practice standard in place of the E 20 (FD20) minimum in Approved Document B Volume 1.",
    "Studs and tracks to BS EN 14195, not less than 0.5mm gauge, in matching galvanised steel U-tracks at head and floor, the tracks fixed securely to the substrate with fixings appropriate to it. Reduce the studs to 400mm centres where higher impact resistance is required or where the partition carries a heavy finish such as tiling. Mineral wool of 10–45 kg/m³ density.",
    "Boards to BS EN 520, moisture-resistant in bathrooms and kitchens, fixed with drywall screws at 300mm centres, joints staggered and finished with joint tape and filler. Finish with a plaster skim. Cables within the stud cavity to be protected by grommets, and any notching or opening of studs to follow the manufacturer's guidance. Where a tested performance is relied on, use a proprietary system installed to the manufacturer's tested details — British Gypsum, Knauf, Siniat or equivalent."]},
  {g:"IF", c:"Works Within Flats", t:"Intermediate Floor Within a Maisonette", u:"40 dB Rw",
   tgt:"To meet Requirement E2 between a bedroom or WC and other rooms within the same flat, and 30 minutes fire resistance where the floor is within a flat with a floor more than 4.5m above ground",
   p:[
    "Floor within a two-storey flat of 47mm x 220mm C24 solid joists or metal web joists at 400mm or 600mm centres to the designer's specification, 22mm tongued and grooved P5 chipboard glued and screwed, 100mm mineral wool of not less than 10 kg/m³ between the joists, and a 12.5mm plasterboard ceiling of not less than 10 kg/m² (15mm or two layers where 30 minutes fire resistance is required to protect the internal stair enclosure). Strutting at mid-span for spans over 2.5m, joists doubled under parallel partitions and trimmed at the stair, and hangers to BS EN 845-1 at masonry bearings. Where the maisonette floor is also over another flat it is a separating floor and the Separating Floors build-ups apply instead."]},
  {g:"GF", c:"Ground Floors", t:"Ground Floor Slab — Insulation Over", u:"0.12 W/m²K",
   tgt:"To achieve a maximum U-value of 0.13 W/m²K, confirmed by the SAP assessment for the ground-floor flats", mf:{"k":"floorSolid","lim":0.13,"p":{"ground":"clay","insulation":"k103","thickness":130,"slab":"c150","finish":"screed75","edge":"e25x150","pa":0.5,"wall":300},"s":[{"r":"floor","f":"130mm Kingspan Kooltherm K103 Floorboard (thermal conductivity 0.019 W/mK)"}]}, p:[
    "Ground floor of a 150mm minimum reinforced concrete slab or precast beam and block deck to the structural engineer's design, a 1200 gauge polyethylene damp proof membrane lapped and taped and linked to the damp proof course, gas protection membrane where the site investigation requires it, 130mm Kingspan Kooltherm K103 Floorboard (thermal conductivity 0.019 W/mK) with 25mm perimeter upstands, a separating layer, and a 75mm screed. Where the ground floor is over an undercroft car park or an unheated space, the floor is an exposed floor and 130mm of the same board with a 15mm fire-rated soffit board calculates at 0.14 to BS EN ISO 6946, or 150mm at 0.12.",
    "This build-up calculates at 0.12 W/m²K to BS EN ISO 13370 for a building footprint with a perimeter/area ratio of 0.5 on clay; the ratio for the actual footprint is to be entered before the thickness is confirmed."]},
  {g:"RF", c:"Roofs", t:"Warm Deck Flat Roof — Concrete or Metal Deck", u:"0.10 W/m²K",
   tgt:"To achieve a maximum U-value of 0.11 W/m²K, confirmed by the SAP assessment for the top-floor flats", mf:{"k":"flat","lim":0.11,"p":{"insulation":"tr26","thickness":220,"deck":"concrete","slab":150,"fixing":"adhered"},"s":[{"r":"flat","f":"220mm Kingspan Thermaroof TR26 LPC/FM (thermal conductivity 0.022 W/mK)"}]}, p:[
    "Warm deck flat roof of a concrete slab or profiled metal deck to the structural engineer's design designed to a fall of not less than 1:40 so that a finished fall of not less than 1:80 is achieved after construction deviations and deflection, in accordance with BS 6229, a vapour control layer fully bonded with laps sealed, 220mm Kingspan Thermaroof TR26 LPC/FM (thermal conductivity 0.022 W/mK) in two layers of 110mm break-bonded and fully adhered or mechanically fixed with the fastener correction included, and a single ply or reinforced bitumen membrane waterproofing system to the manufacturer's specification and BBA certificate with 150mm upstands, outlets, overflows and edge trims. Where the building has a storey more than 11m above ground the roof insulation within 1.5m of a boundary or a higher external wall is to be Class A2-s1, d0 or better, and mineral wool or cellular glass of 0.038 W/mK at 300mm is to be used in that zone.",
    "This build-up calculates at 0.10 W/m²K to BS EN ISO 6946 fully adhered on a 150mm concrete deck; 200mm calculates at 0.11 on a concrete deck, meeting the notional value with no margin. Roof-mounted plant, photovoltaics and access routes are to be on paving supports or a proprietary system, with the waterproofing protected and a guarded access route where maintenance is regular."]},
  {g:"RF", c:"Roofs", t:"Pitched Roof — Insulation at Ceiling Level", u:"0.11 W/m²K",
   tgt:"To achieve a maximum U-value of 0.11 W/m²K, confirmed by the SAP assessment",
   p:[
    "Trussed rafter roof to BS EN 14250 and the truss designer's design, tiles or slates on battens over a vapour permeable underlay to BS 5534, the wall plate strapped down at not more than 2m centres, a ceiling of 12.5mm plasterboard with a vapour control layer, and 100mm mineral wool of 0.044 W/mK between the ceiling ties with 300mm laid over, to a total of 400mm. Ventilation equivalent to a 10mm continuous gap at two opposite eaves with eaves ventilators and insulation stops, and high-level ventilation where the underlay is not vapour permeable.",
    "The separating walls between the top-floor flats are to be carried up tight to the underside of the roof covering and fire stopped, so that the roof void is divided into compartments over each flat; the ceiling to the roof void is the compartment boundary where the void is not divided and is then to achieve 60 minutes fire resistance. This build-up calculates at 0.11 W/m²K to BS EN ISO 6946 allowing for the joist fraction at 400mm centres."]}
 ],
 notes:[
  {c:"Planning", t:"Planning Permission and Conditions", p:[
    "The building is to be constructed strictly in accordance with the approved planning drawings and the conditions of the permission. Conditions commonly relevant to this specification are those imposing optional requirements M4(2) or M4(3) on a proportion of the flats, the 110 litres per person per day water efficiency standard, cycle and refuse storage, the energy strategy and any carbon reduction target beyond the Building Regulations, SuDS and drainage, noise insulation against external noise, and construction management. Where a condition requires a standard higher than the Regulations, the condition governs.",
    "Building Regulations approval does not confer planning permission, and planning permission does not confer Building Regulations approval."]},
  {c:"General Notes", t:"Compliance and Scope", p:[
    "All work to be carried out in accordance with the Building Regulations 2010 as amended, the current Approved Documents, the British Standards referred to in them, the drawings and the structural engineer's details. Materials to be fit for their purpose, CE or UKCA marked where a designated standard applies, and installed in accordance with the manufacturer's instructions and any third-party certificate. Where a British Standard has been superseded the current edition applies.",
    "Where there is a conflict between documents, the drawings take precedence for dimensions, the engineer's information for structure and the fire strategy for fire matters. Discrepancies are to be referred to the designer before the work proceeds.",
    "Materials and workmanship (Regulation 7): every material is to be appropriate for the circumstances in which it is used, of a suitable nature and quality, adequately mixed or prepared and applied so that it performs the function for which it is designed, and workmanship is to be of the standard Approved Document 7 describes — products with a UKCA or CE marking, a British Board of Agrément certificate or independent third-party certification used within the scope of that certificate, work to the BS 8000 series or the manufacturer's instructions, and any material without an established track record supported by evidence of its suitability before building control is asked to accept it. Regulation 7(2), on the combustibility of the materials in an external wall where a storey is more than 18m above ground, is dealt with in the Building Height note."]},
  {c:"General Notes", t:"CDM, Party Wall and Completion Certificate", p:[
    "The notices to building control under Regulation 16 (notice of intention, commencement notice and completion notice) and the inspection stages are set out in the Regulation 16 note; a completion certificate is to be obtained for the block and given to the client with the competent person and commissioning certificates. The Construction (Design and Management) Regulations 2015 apply: the client is to appoint a principal designer and principal contractor in writing, notify the project to the HSE on an F10 where it will exceed 30 working days with more than 20 workers at once or 500 person-days, a construction phase plan is required before work starts, and the health and safety file is to be handed over at completion. Where the block adjoins or is within 3m of a neighbouring building, or excavations fall within 6m and below the 45 degree line from the neighbour's foundations, Party Wall etc. Act 1996 notices are to be served with the engineer's drawings and no notifiable work started until the Act has been complied with."]},
  {c:"General Notes", t:"Information to Building Control and Regulation 38", p:[
    "Before work starts: the fire strategy, structural calculations, the design-stage SAP for every flat with the block-level compliance summary, the site investigation, the drainage design, the sound insulation strategy with Robust Details registration or a test proposal, and the ventilation and overheating reports. At completion: the as-built SAPs, BREL reports and EPCs, pressure test certificates for the tested flats, sound test results, commissioning certificates for heating, hot water, ventilation, fire alarm, smoke control, emergency lighting, sprinklers and lifts, the electrical and gas certificates, and the water efficiency calculations.",
    "Under Regulation 38 the fire safety information for the building is to be handed to the responsible person not later than completion: the fire strategy, the as-built drawings showing compartmentation, fire doors, cavity barriers and fire stopping with their specifications, the fire alarm, smoke control and firefighting provisions, and the maintenance requirements. A copy of the handover is to be given to building control."]},
  {c:"General Notes", t:"Regulation 16 Notices — Commencement and Completion", p:[
    "Regulation 16 of the Building Regulations 2010 (as amended in October 2023) requires three notices to the building control body: notice of intention to start work, given so that at least two clear days elapse before work begins; a commencement notice within five days of the work being regarded as commenced under Regulation 46A, which for a new building is when the sub-structure including the ground floor structure is complete, after which the authority has four weeks to reject the notice; and a completion notice within five days of completion. The completion notice must give the name, address, telephone number and email of the client, the principal contractor and the principal designer, state that the work is complete, include a signed statement by the client that the work complies with the Building Regulations, and include signed statements from the principal designer and principal contractor confirming that they have fulfilled their duties under Part 2A with the dates of their appointments; where a statement cannot be obtained the reason is to be given. Where the block is a higher-risk building (see the Building Height note) the Building Safety Regulator's procedures apply instead of these notices.",
    "Inspection stages to be notified as they arise: excavations before concreting, foundations before covering, damp proof courses and membranes, oversite, structural steel and fire-resisting construction before it is closed up, insulation before it is boarded, drains before backfilling and on test, and completion. Certificates from competent person schemes (electrical, gas, heating appliances) and the commissioning notices for fixed building services, ventilation and pressure tests are to be given to building control within five days of the work or test being completed and copied to the client with the completion certificate, which purchasers' solicitors will ask for; the full schedule of completion information is in the Information to Building Control and Regulation 38 note.",
    "NOTE — The two-day and five-day limbs are separate duties. Missing the commencement notice means the work is not treated as commenced for transitional purposes, which matters where an edition of the Approved Documents is about to change (Approved Document L and F 2026 editions, in force 24 March 2027)."]},
  {c:"Building Height & Applicable Regime", t:"Height Thresholds That Change the Requirements", p:[
    "The requirements for a block of flats change at defined building heights measured from the lowest ground level adjoining the building to the top floor surface of the highest storey containing a flat (excluding a top storey that is only roof-top plant). The thresholds relevant to this specification are: 4.5m (escape from a single flat or an inner room above this height requires a protected route); 5m (compartment walls and floors increase from 30 to 60 minutes); 11m (sprinklers throughout the flats, a secure information box and wayfinding signage under Approved Document B Volume 1, the external wall material provisions in its Section 12, the Fire Safety (England) Regulations 2022 duties on flat entrance and common fire doors, and the height above which a timber compartment floor is not to be used in this specification); and 18m (Regulation 7(2) ban on combustible materials in external walls and specified attachments, the higher-risk building regime under the Building Safety Act 2022 with Gateway 2 approval by the Building Safety Regulator before work starts, firefighting shafts and lifts, an evacuation alert system to BS 8629, and 90 minutes fire resistance rising to 120 minutes above 30m).",
    "This specification is written for a block with no storey more than 11m above ground level unless the drawings state otherwise. Where the building exceeds 11m, the fire strategy, the external wall specification and the approval route are to be reviewed clause by clause before submission, and where it exceeds 18m the application is to the Building Safety Regulator and not to the local authority or an approved inspector.",
    "NOTE — Height is measured to the top floor surface, not the roof, and the lowest adjoining ground is used. A four-storey block on a sloping site can exceed 11m at the low side; check the height on the section before the fire strategy is fixed."]},
  {c:"Site Preparation & Contaminants", t:"Site Preparation", p:[
    "Strip all vegetable soil from the footprint; carry out a desk study and intrusive investigation to BS 10175 where the site is previously developed, and agree any remediation strategy and verification with the local authority before work starts. Ground gas and radon protection as the Radon and Ground Gas Protection note. Subsoil drainage where groundwater is encountered, and existing land drains intercepted and re-routed."]},
  {c:"Site Preparation & Contaminants", t:"Demolition and Existing Services", p:[
    "Where existing buildings are demolished, notice under Section 80 of the Building Act 1984 is to be given to the local authority not less than six weeks before demolition and the Section 81 notice complied with, utilities disconnected and capped at the boundary, asbestos surveyed to the Control of Asbestos Regulations 2012 and removed by a licensed contractor before demolition, and existing foundations, drains and basements located and grubbed out or filled with compacted material and recorded; old foundations are not to be built on unless assessed by the engineer. Retained trees to be protected to BS 5837 and the planning conditions on demolition and construction management complied with."]},
  {c:"Site Preparation & Contaminants", t:"Radon and Ground Gas Protection — Detail", opt:1, p:[
    "Where the site is in a radon affected area on the UK radon map, protection to BR 211 is to be built in. Basic protection is a radon-resistant membrane, of a grade certified for radon resistance (typically 1600 gauge / 400 micron polyethylene or a reinforced or aluminium-cored membrane), laid across the whole footprint in place of the standard damp proof membrane with laps of not less than 300mm sealed with gas-resistant tape, every penetration sealed with a top hat, and the membrane carried across the cavity to link with a cavity tray or the damp proof course in both leaves so the barrier is continuous; the slab is to be laid over sound compacted fill so the membrane cannot tear. Full protection, where the map shows the higher probability band, adds a radon sump beneath the slab connected to a capped pipe taken to the outside so a fan can be fitted later, or, for a suspended floor, a cross-ventilated void of not less than 150mm with the vents on opposite sides; a radon test after occupation and the fan fitted if the result is high. Where the site investigation identifies landfill gas, hydrocarbons or volatile organic compounds, gas protection is to be designed to BS 8485 and CIRIA C735 with a specialist membrane, its installation independently inspected and a verification report given to building control.",
    "NOTE — Confirm the radon status for the postcode on the UK radon map and the gas screening value from the site investigation before the ground floor build-up is finalised; the membrane grade and any sump or ventilated void follow from them."]},
  {c:"Structure", t:"Structural Design and Disproportionate Collapse", p:[
    "All structural work to the design and details of the structural engineer, to Eurocodes and their UK National Annexes, with calculations and details submitted to building control before the relevant work begins. Buildings of five storeys or more are Consequence Class 2B under Approved Document A Section 5 and are to be designed for disproportionate collapse by effective horizontal and vertical tying, notional removal of supporting members or key element design; buildings of four storeys or fewer are Class 2A and require effective horizontal ties or anchorage of suspended floors to walls. Lateral restraint straps, movement joints, lintels and padstones as the engineer's details."]},
  {c:"Structure", t:"Beams, Lintels, Restraint and Openings", p:[
    "Structural steel and concrete beams and columns to the engineer's design with the connections, bearing plates and padstones specified, fire protected for the compartment period (60 minutes in most blocks, 90 above 18m) by encasement in tested board systems, sprayed protection or intumescent coatings applied to the certified thickness for the section factor, with the certificates included in the Regulation 38 information. Lintels over openings in masonry to be proprietary insulated steel lintels to BS EN 845-2 or precast prestressed concrete lintels with not less than 150mm end bearing and a cavity tray above. Lateral restraint straps at every floor and roof level at not more than 2m centres to walls parallel to the joists and at the wall plate, or the floor slabs designed to restrain the walls, and openings in loadbearing masonry within the limits of Approved Document A Section 2C or to the engineer's design with the wall returns and piers shown on the drawings."]},
  {c:"Foundations", t:"Foundations", p:[
    "Foundations to the structural engineer's design following the site investigation, whether strip, trench fill, pad, raft or piled, with the sulfate and chloride class of the concrete from BS 8500 for the ground conditions and heave precautions where shrinkable clay and trees are present in accordance with NHBC Chapter 4.2. Piling to be by a specialist to the engineer's specification with load tests where required, and vibration and noise limited as the construction management plan. All excavations to be inspected by building control before concrete is placed.",
    "Foundations are to be taken below the invert of any adjacent drain and not undermined by it, with the drain sleeved or bridged with 50mm clearance and flexible joints each side where it passes through, and steps in strip or trench-fill foundations are not to exceed the foundation thickness, the higher foundation overlapping the lower by not less than twice the step, the thickness or 300mm whichever is greater (1m for trench fill). Where the ground is filled, soft or variable a raft or piled foundation to the engineer's design is used. The tabulated strip foundation widths in Approved Document A Section 2E are a fallback for small buildings within the scope of Section 2 of that document (residential buildings of not more than three storeys) on firm uniform ground and are not to be relied on for a block outside that scope."]},
  {c:"Ground Floors", t:"Ground Floor Notes", p:[
    "Damp proof membranes to be linked to the damp proof course in every external and internal wall, and gas membranes sealed to the slab edge and around every penetration with the manufacturer's tapes and top hats. Perimeter upstand insulation to all ground floors, and the screed isolated from the walls with a compressible strip. Ducts and risers through the ground floor to be fire stopped at the slab where they enter a flat and sealed to the membranes."]},
  {c:"Works Within Flats", t:"Partitions, Stairs, Doors and Loadbearing Walls Within Flats", p:[
    "Internal partitions within a flat as the Internal Partition build-up in metal stud, timber stud or 100mm blockwork; loadbearing masonry walls within a flat of 100mm or 140mm blockwork to the engineer's design in 1:1:6 mortar with the block strength specified, plastered or lined, and carried down to the structure below. Flat entrance doors are FD30S self-closing doorsets tested for both fire and security as the Escape Within the Flat and Flat Entrance Doors note; internal doors are standard doorsets other than those onto a protected entrance hall, which are specified in that note.",
    "A stair within a maisonette is a private stair to Approved Document K: pitch not more than 42 degrees, rise between 150mm and 220mm, going not less than 220mm, twice the rise plus the going between 550mm and 700mm, all rises and goings in a flight equal, headroom of 2m over the pitch line and landings, and a handrail on at least one side at 900mm to 1000mm above the pitch line, on both sides where the flight is 1m or wider, with not less than 600mm clear between handrails where two are fitted. Tapered treads to have a going of not less than 50mm at the narrow end and to satisfy the going rule at the centre line (or 270mm from the narrow end where the stair is wider than 1m); landings at the top and bottom of every flight at least as long as the flight is wide and level, with no door swinging over a landing other than a cupboard door which leaves 400mm clear; open risers not to pass a 100mm sphere; timber stairs to BS 585 with the strings, treads and risers glued and wedged and the newels bolted to the floor structure. Guarding of 900mm to every open side and landing, not climbable and not passing a 100mm sphere, designed for the horizontal load in BS EN 1991-1-1 (0.36 kN/m for a dwelling). Where the upper floor of the maisonette is more than 4.5m above ground and there is no alternative exit from it, the stair is to be enclosed as a protected stair in 30 minutes fire-resisting construction with FD30S fire doorsets (E 30 Sa, with intumescent strips and cold smoke seals) fitted with a self-closing device, adopted as the practice standard in place of the E 20 (FD20) minimum in Approved Document B Volume 1 to the rooms off it (see the Escape Within the Flat note)."]},
  {c:"Works Within Flats", t:"Heating and Hot Water Within Flats", p:[
    "Where each flat has its own system rather than a communal heat network (see the Heating and Hot Water note under Services): a heat pump or direct electric system, or a condensing gas combination boiler of not less than 92 per cent ErP seasonal efficiency with a room-sealed flue to Approved Document J terminating clear of openings, balconies and the neighbouring flats' windows and not less than 50mm from combustible material, inspection hatches of 300mm x 300mm at every joint and change of direction where a flue runs in a void, a carbon monoxide alarm to BS EN 50291 between 1m and 3m from the appliance, and for a combination boiler one of the additional efficiency measures in the Domestic Building Services Compliance Guide (flue gas heat recovery, weather or load compensation, or a smart thermostat with automation and optimisation). Wet systems designed for a maximum flow temperature of 55°C with radiators or underfloor heating sized accordingly; controls to Approved Document L Volume 1 Section 5 with time and temperature control of every heating zone, thermostatic radiator valves, a cylinder thermostat and time control for hot water independent of the heating, and a boiler interlock; primary and accessible pipework insulated to Table 4.4. Heat pumps to MCS MIS 3005 with a room-by-room heat loss calculation, emitters and cylinder sized to the design flow temperature and any back-up heater interlocked so that it never leads; the siting of outdoor units is in the Renewable Energy note. Direct electric systems by panel heaters with time and temperature control in each room or storage heaters with automatic charge control; electric underfloor heating on a dedicated circuit with 30mA RCD protection and a floor sensor thermostat to each zone, with continuity and insulation tests recorded before the floor is covered.",
    "Wet underfloor heating designed to BS EN 1264 with the floor surface temperature limited to 29°C (27 with resilient finishes), insulation beneath the pipes of not less than ten times the resistance of the floor finish (R 0.75 m²K/W minimum on intermediate and separating floors, laid so that the acoustic resilient layer is not bridged), 25mm edge insulation, a 65mm minimum screed over the pipes with movement joints at doorways, zone boundaries and bays over 40m² or 8m long, the system pressure tested before the screed is placed and commissioned to BS EN 1264-4 with the manifold zones labelled. Hot water by the combination boiler, an unvented cylinder or an electric water heater, with the storage temperature, safety devices, discharge pipework and the 48°C limit to baths as the Water Supply, Efficiency and Hot Water Safety note. Wood burning stoves and oil-fired appliances are not to be installed in flats other than with a flue, air supply and hearth designed to Approved Document J and the fire strategy's agreement, and open-flued appliances are not to be installed in bedrooms or bathrooms. The commissioning certificate and the Benchmark record for every appliance to be given to building control and the occupier."]},
  {c:"Additional Notes for Walls & Roofs", t:"Damp Proof Courses, Cavity Trays, Ties, Movement and Walls Below Ground", p:[
    "Damp proof course in both leaves at not less than 150mm above finished external ground level, stepped where the ground falls and linked to the floor damp proof membrane and to any tanking; cavity trays with stop ends and weep holes at not more than 900mm centres over every opening, at abutments with lower roofs and balconies, at brick support angles and at the head of the wall below copings; insulated cavity closers to every opening; stainless steel wall ties to BS EN 845-1 at 450mm vertical and 900mm horizontal centres, staggered, at not more than 300mm vertical centres within 225mm of jambs and movement joints (PD 6697), of the type and length for the cavity width; movement joints in clay brickwork at not more than 12m and in blockwork at not more than 6m, at changes of height and thickness and at the slab edge on a framed building where the brickwork is supported at each floor, with debonded ties across the joint and a compressible filler and sealant. Cavity barriers at every compartment line and at the top of every cavity. Walls below ground to be retaining walls to the engineer's design waterproofed to BS 8102:2022 to the grade for the use of the space behind, with the cavity filled with concrete to 225mm below the damp proof course and a land drain at the base connected to the surface water system; where a basement car park or plant room is formed, the Basement Conversion specification build-ups for Type A plus Type C or Type B protection apply."]},
  {c:"Additional Notes for Walls & Roofs", t:"Roof Coverings, Warm Roof Option, Leadwork and Rainwater", p:[
    "Roof coverings fixed to BS 5534 with the fixing schedule for the site exposure and the building height (every tile fixed on a building over 12m to eaves or in a severe exposure zone), dry-fix ridge and verge systems, the underlay carried into the gutter over an eaves support tray, and the eaves and verges detailed with the fire stopping of the roof void at every separating wall. Where a pitched roof over top-floor flats is insulated at rafter level with the rafters exposed or a flat ceiling line, insulation over and between the rafters as a warm roof (150mm Kingspan Kooltherm K107 between plus 75mm over as a sarking board calculates at 0.12 W/m²K, 100mm over at 0.10) with counter-battens fixed through the sarking into the rafters to the board manufacturer's schedule. Leadwork to the Rolled Lead Sheet Manual (Code 4 flashings and soakers, Code 5 valleys and gutters, Code 6 wide gutters, pieces not exceeding 1.5m) with stepped flashings tucked 25mm into the joint; valleys lead-lined or GRP on valley boards or a proprietary dry valley. Gutters and downpipes to BS EN 12056-3 for the roof area with the downpipes taken to the surface water drainage through trapped gullies, and every flat roof with outlets and overflows sized for the roof area and the design storm. Vapour control layers to every insulated roof on the warm side and roof voids ventilated or the roof built as a warm roof.",
    "Hipped roofs: hip rafters and any crown rafter to the structural engineer's design, each hip rafter carried down to the wall plate at the corner and restrained by a hip iron at its foot, jack rafters birdsmouthed to the wall plate and skew-nailed to the hip, hip tiles bedded and mechanically fixed or a dry-fix hip system to the tile manufacturer's details and BS 5534, and the roof insulation carried to the eaves on every slope with the eaves ventilation path kept clear at each hip."]},
  {c:"Common Areas & Escape Stairs", t:"Common Escape Stair", p:[
    "The common stair to be a protected stairway enclosed in fire-resisting construction of not less than the compartment period, with FD30S self-closing doors from every lobby or corridor, no gas service pipes, meters or combustible storage within it, a final exit door opening directly to the open air, and the stair itself of limited combustibility construction where the building has a storey more than 18m above ground. Stair to Approved Document K for a common stair: pitch not more than 38 degrees, rise between 150mm and 170mm, going not less than 250mm, minimum clear width 1000mm (1100mm where the stair is a firefighting stair or serves M4(3) flats), landings at least the stair width, handrails on both sides at 900mm to 1000mm with a further rail at 600mm where children use the stair, and guarding at 900mm on flights and 1100mm at landings.",
    "Every storey is to have a corridor or lobby between the flat entrance doors and the stair, with smoke control to Approved Document B Volume 1 Section 3: on each storey an automatic opening vent of not less than 1.5m² free area on an external wall of the corridor or lobby next to the stair, or an automatic vent discharging into a smoke shaft of not less than 1.5m² cross-sectional area, or a mechanical smoke ventilation system designed to BS EN 12101-6 and the fire strategy; and a vent of not less than 1m² free area to the outside at the head of the stair, automatic in a single-stair building and openable by the fire service where more than one stair serves the building. Emergency escape lighting to BS 5266-1 to all common escape routes, and exit signage to BS ISO 3864 and BS 5499-4."]},
  {c:"Common Areas & Escape Stairs", t:"Common Corridors and Travel Distance", p:[
    "Flat entrance doors to open onto a common corridor or lobby, not directly onto the stair, with a maximum travel distance from the flat entrance door to the stair door of 7.5m where escape is in one direction only and 30m where escape is available in two directions. A dead-end corridor longer than 7.5m is to be subdivided from the rest by a self-closing FD30S door. Corridors to be not less than 1200mm clear where M4(2) or M4(3) flats are served, otherwise 1050mm, with fire-resisting construction to the compartment period and the ceiling void either fire stopped or the corridor construction carried to the soffit."]},
  {c:"Common Areas & Escape Stairs", t:"Lifts", p:[
    "A passenger lift is to be provided where any flat is above or below the entrance storey and M4(2) or M4(3) applies to it, and is recommended in every block of more than three storeys; where provided it is to be a passenger lift to BS EN 81-20 and 81-70 with a car of not less than 1100mm x 1400mm, landing controls at 900mm to 1100mm, a level landing of 1500mm x 1500mm at each floor, and the lift well enclosed in fire-resisting construction where it is within the protected stair or opens into a corridor. Where the building has a storey more than 18m above ground a firefighting lift is required; where M4(3) wheelchair user dwellings are above the entrance storey an evacuation lift or a lift with a protected lobby is to be provided as the fire strategy. The lift is to be commissioned and its documentation included in the Regulation 38 information."]},
  {c:"Common Areas & Escape Stairs", t:"Undercroft and Basement Car Parks", p:[
    "An undercroft or basement car park beneath the flats is a separate compartment separated from the flats by a compartment floor and walls of not less than 60 minutes fire resistance, with the single common stair entered from the car park only through a ventilated protected lobby and no ancillary accommodation opening directly onto the stair; escape from the car park by two directions where the travel distance exceeds 18m and a final exit not passing through the flats. Ventilation to Approved Document F Volume 2 paragraphs 1.38 and 1.39: the ventilation rate designed, and the equipment installed, to limit carbon monoxide to a maximum average concentration of 30 parts per million over an eight hour period and a maximum peak concentration of 90 parts per million over any 15 minute period at positions such as ramps and exits. As the alternative that paragraph 1.39 allows, natural ventilation by openings at each car parking level having a minimum aggregate equivalent area of one twentieth of the floor area at that level, with not less than 25 per cent of that aggregate equivalent area on each of two opposing walls; or mechanical ventilation, being either permanent natural ventilation openings of a minimum equivalent area of one fortieth of the floor area together with a mechanical system capable of at least three air changes per hour, or, for a car park in a basement, a mechanical system capable of at least six air changes per hour, and in either case a local ventilation rate of at least ten air changes per hour at exits and ramps where cars queue inside the building. Smoke clearance for firefighting is a separate provision from the pollution control above: the smoke ventilation, the fan temperature rating and duration and the secondary supply are to be taken from Section 11 of Approved Document B Volume 2 and from the fire engineer's strategy for the building. The soffit insulation and any lining to be of limited combustibility, the floor above insulated as an exposed floor to 0.13 W/m²K, drainage through a petrol interceptor, and electric vehicle charge points sited as the fire strategy requires with the cable routes and load management as the Part S note.",
    "NOTE — The pollution control figures above are from Approved Document F Volume 2 paragraphs 1.38 and 1.39 and are confirmed. The smoke clearance provisions are in Section 11 of Approved Document B Volume 2, which is not held in this library: obtain the fan rating, duration and secondary supply from that section or from the fire engineer before issue."]},
  {c:"Means of Escape & Fire Regs", t:"Escape Within the Flat and Flat Entrance Doors", p:[
    "Each flat is to have either a protected entrance hall giving access to every habitable room, enclosed in 30 minutes fire-resisting construction with FD30S fire doorsets (E 30 Sa, with intumescent strips and cold smoke seals) fitted with a self-closing device, adopted as the practice standard in place of the E 20 (FD20) minimum in Approved Document B Volume 1, with the travel distance from the flat entrance door to the door of every habitable room not exceeding 9m and any glazing in the hall enclosure fire-resisting in a tested frame (uninsulated integrity-only glazing permitted only above 1.1m from the floor); or an open-plan arrangement where every habitable room has a door to a common area or an escape window, or where the flat is protected by a sprinkler system to BS 9251 with the cooking area enclosed or separated as Approved Document B Volume 1 Section 3. Escape windows are available only where the floor is not more than 4.5m above ground and are to have an openable area of not less than 0.33m² and not less than 450mm x 450mm, with the bottom of the openable area not more than 1100mm above the floor and not less than 800mm unless guarded, openable without a key from inside. No bedroom is to be an inner room opening off a kitchen or living room without an alternative exit or an escape window; in a studio flat the cooking area is to be sited so that the escape route from the sleeping area to the entrance door does not pass through it, or enclosed, or fitted with a heat alarm and a sprinkler where the layout cannot achieve that.",
    "Flats with a floor more than 4.5m above ground and a protected entrance hall meet the requirement by the hall; a flat on two levels with a floor above 4.5m is to have a protected internal stair or an alternative exit from the upper level.",
    "Flat entrance doorsets to be FD30S fire doorsets (E 30 Sa) with intumescent strips and cold smoke seals, a self-closing device, three hinges of a material with a melting point above 800°C, a lock that can be opened from inside without a key (a thumb-turn) so that escape is never impeded, a letter plate with an intumescent liner where fitted, and no glazing other than fire-resisting glazing in a tested frame, tested as a complete doorset to BS EN 1634-1 or BS 476-22 and installed to the manufacturer's instructions with the certification label retained; the same doorset is the Part Q secure door as the Security note."]},
  {c:"Means of Escape & Fire Regs", t:"Fire Detection and Alarm", p:[
    "Each flat to have a fire detection and alarm system to BS 5839-6 of Grade D1 Category LD2: mains powered smoke alarms to BS EN 14604 with an integral tamper-proof standby supply, interlinked within the flat, in the entrance hall and every circulation space, in the principal habitable room and in any room in which a fire could start that opens onto the escape route, with a heat alarm to BS 5446-2 in the kitchen. This exceeds the Grade D2 Category LD3 minimum in Approved Document B Volume 1 for new dwellings and is adopted as this practice's standard. Alarms to be ceiling mounted not less than 300mm from any wall or light fitting, within 3m of every bedroom door and so that no point in a hall longer than 7.5m is more than 7.5m from an alarm; a carbon monoxide alarm to BS EN 50291 in every room containing a fixed combustion appliance; and the design, installation and commissioning certificate for each flat given to building control.",
    "The common parts of a building with a stay-put strategy do not normally have a communal alarm, and detection is not to be installed in the common areas unless the fire strategy requires it for the smoke control system, in which case it is to BS 5839-1 and the alarm is not to sound in the flats. Where the building has a storey more than 18m above ground an evacuation alert system to BS 8629 is required."]},
  {c:"Means of Escape & Fire Regs", t:"Compartmentation and Fire Stopping", p:[
    "Every flat is a separate compartment. Compartment walls and floors to have 60 minutes fire resistance where any storey is more than 5m above ground (30 minutes where none is), 90 minutes where the top storey is more than 18m above ground and 120 minutes where it is more than 30m, carried through the full depth of the floor and to the underside of the roof covering, with every junction, penetration and void fire stopped with tested products installed to the manufacturer's certificate and recorded with photographs for the Regulation 38 information. Cavity barriers at every compartment line in every cavity, at the edge of every cavity, around openings and at not more than 20m centres in ceiling voids, all identified on the as-built drawings.",
    "Pipes through compartment walls and floors to be sleeved and fire stopped, with fire collars or wraps to plastic pipes; ductwork fitted with fire dampers at every compartment line or the duct itself fire rated; and risers and service shafts enclosed as protected shafts with fire-resisting access panels. Flat entrance doors, riser doors and lobby doors to be certificated fire doorsets with the certification label retained."]},
  {c:"Means of Escape & Fire Regs", t:"External Walls, Balconies and Boundaries", p:[
    "External walls of a block of flats with a storey more than 11m above ground are to be constructed in accordance with Approved Document B Volume 1 Section 12 with the insulation, membranes, cavity barriers and cladding of the classes stated there, and where the storey is more than 18m every component of the external wall and every specified attachment including balconies is to be Class A2-s1, d0 or A1 under Regulation 7(2), other than the components exempted in Regulation 7(3). Below 11m the external wall is to meet the requirements for surfaces and unprotected areas in Sections 10 and 11 for a residential building.",
    "Balconies to be of non-combustible construction where the building has a storey more than 18m above ground and are recommended to be so at 11m and above; balcony decking, soffits and balustrade infills are to be of limited combustibility and the balcony is not to be positioned so that fire can spread from one to another or from a window below. Boundary distances and unprotected areas to Section 11, with external walls within 1m of the relevant boundary having the compartment period of fire resistance (60 minutes where any storey is more than 5m above ground) from both sides."]},
  {c:"Means of Escape & Fire Regs", t:"Sprinklers", p:[
    "Where the building has a storey more than 11m above ground a sprinkler system is to be installed throughout the flats to BS 9251 by a certificated installer, with the water supply, tank and pump arrangement designed for the duration and pressure in the standard and the system commissioned and maintained under a contract handed over with the Regulation 38 information. Where sprinklers are used to justify an open-plan flat layout below 11m, they are to BS 9251 Category 2 with coverage to every room other than as the standard permits."]},
  {c:"Means of Escape & Fire Regs", t:"Access and Facilities for the Fire Service", p:[
    "Vehicle access for a pump appliance to within 45m of every point on the ground floor of every flat, or to within 45m of every flat entrance door where the building has a storey more than 11m above ground and no fire main, with the route not less than 3.7m wide between kerbs, with turning facilities where the dead end exceeds 20m, and capable of carrying 12.5 tonnes. Where the building has a storey more than 18m above ground, a firefighting shaft with a dry rising main (wet above 50m) is required with an outlet on every storey and an inlet within 18m of the appliance position. A secure information box to BS 8629 Annex A and a wayfinding signage scheme to Section 15 where the building has a storey more than 11m above ground. Fire hydrants within 90m of the fire main inlet or, where none exists, within 90m of the entrance."]},
  {c:"Sound Insulation (Part E)", t:"Separating Walls and Floors — New Build Standard", p:[
    "Separating walls and floors between flats, and between a flat and any other part of the building, to achieve not less than 45 dB DnT,w + Ctr airborne sound insulation, and separating floors not more than 62 dB L'nT,w impact sound, in accordance with Approved Document E Table 1a for purpose-built flats. Compliance to be shown either by construction to registered Robust Details or by pre-completion testing, as the Part E Testing and Robust Details Evidence note.",
    "Flanking constructions, junctions, service penetrations and the isolation of floating floors and independent ceilings are to be exactly as the detail, and the site is to be inspected at each stage before the next layer is placed. Corridor walls, lift shaft walls and plant room walls are separating walls for the purposes of Part E and are to be constructed accordingly, with the lift and plant selected and mounted to limit structure-borne noise to the flats.",
    "NOTE — The new-build standard is 45/62; the conversion standard is 43/64. Flats in a new build are to be designed to the new-build values, and the sound test results are to be submitted to building control before the completion certificate is issued."]},
  {c:"Sound Insulation (Part E)", t:"Internal Walls and Floors and Reverberation in Common Areas", p:[
    "Internal walls within a flat between a bedroom or a room containing a WC and other rooms to achieve 40 dB Rw using the constructions in Approved Document E Section 5. Common corridors, stairs and entrance halls are to have sound absorbing finishes to Requirement E3 by Method A (an area of Class C absorber at least equal to the floor area of the space, normally as a suspended ceiling or ceiling panels) or by the calculation in Method B, with the absorbers shown on the drawings."]},
  {c:"Sound Insulation (Part E)", t:"Part E Testing and Robust Details Evidence", p:[
    "Pre-completion sound tests are to be carried out when the separating elements, doors and windows are complete but before carpets and soft floor coverings are laid, by a tester accredited by UKAS or registered under the Association of Noise Consultants scheme, at the rate of one set of tests for every ten dwellings of each construction type (a set being two airborne wall tests, two airborne floor tests and two impact floor tests where both elements exist); a failed test is to be followed by remedial work agreed with the tester and a retest of the failed element and any others the building control body requires. Where Robust Details are used instead, the plot registration and purchase statement with the unique reference number are to be given to building control before the separating elements are built, the details built exactly as the handbook including flanking constructions, and the compliance certificate and a report of where each detail was used given to building control at completion; where the detail is not followed on site the plots revert to pre-completion testing."]},
  {c:"Windows, Doors & Glazing", t:"Windows and External Doors", p:[
    "Windows to have a whole-window U-value not exceeding 1.2 W/m²K and in no case worse than 1.6 W/m²K, external doors 1.0 W/m²K notional and 1.6 limiting, with the frame sealed to the air barrier internally and weathered externally. Sills with a projecting drip and cavity closers at all jambs. Glazing in critical locations to be safety glass to BS EN 12600 Class 2 or better. Windows above ground floor level to have guarding to Approved Document K where the sill is below 800mm and, where the window is relied on for cooling under Part O and the drop outside is 1.1m or more, guarding to 1100mm or the opening limited to 100mm by a restrictor (Approved Document O Table 3.1); and windows in common stairs and corridors that open onto the escape route to be restricted so they do not obstruct it. Rooflights to top-floor flats to have a U-value not exceeding 1.7 W/m²K to match the notional dwelling and in no case worse than 2.2 W/m²K, on an insulated kerb of not less than 150mm to a flat roof, and where they are the only openable window in a room to give the purge ventilation area. Escape windows are only relevant to flats with a floor not more than 4.5m above ground; above that height escape is by the protected entrance hall and the common stair.",
    "Where the planning permission imposes a noise condition, the glazing and ventilators are to achieve the sound reduction specified in the acoustic report, and the ventilation strategy is to allow the windows to remain closed where the report requires it."]},
  {c:"Ventilation", t:"Ventilation of the Flats — Approved Document F", p:[
    "Each flat to be ventilated to Approved Document F Volume 1 by a system from Table 1.2 consistent with the SAP input: natural ventilation with background ventilators and intermittent extract (System 1) is not permitted where the design air permeability is less than 5 m³/(h·m²) or where the flat is single-aspect and the whole-dwelling rate cannot be achieved, and continuous mechanical extract (System 3) or mechanical ventilation with heat recovery (System 4) is then to be used. Whole-dwelling rate not less than the greater of 0.3 litres per second per square metre and the rate for the number of bedrooms in Table 1.3 (19, 25, 31, 37 and 43 litres per second for one to five bedrooms). Intermittent extract fans to BS EN 13141-4 at not less than 30 litres per second from a cooker hood over the hob (fitted 650mm to 750mm above it, to BS EN 13141-3) or 60 litres per second elsewhere in the kitchen, 30 litres per second from a utility room, 15 litres per second from a bathroom and 6 litres per second from a WC, wired to the light switch with a 15 minute overrun where the room has no openable window, in rigid duct wherever possible with flexible duct limited to 1.5m at final connections and installed to BSRIA BG 43, discharging to the external air through a terminal with a backdraught shutter; extract ducts are not to discharge into the common areas or the roof void, and where they pass through a compartment wall or floor are to be fire dampered or fire rated.",
    "Background ventilators for System 1 to give an equivalent area of not less than 10,000mm² in every habitable room and kitchen of a single-storey flat, 8000mm² in a maisonette on two storeys, and 4000mm² in every bathroom, with not fewer than four ventilators in a one-bedroom flat and five otherwise, set not less than 1700mm above floor level (trickle ventilators in the window heads ordered as part of the window units), with the equivalent area marked or recorded and noise-attenuating ventilators used on facades exposed to traffic or other noise. Purge ventilation to every habitable room by an openable area of not less than one twentieth of the floor area where the window opens more than 30 degrees, or one tenth where it opens between 15 and 30 degrees, or, where the noise or overheating strategy requires the windows to remain closed, a mechanical system giving four air changes per hour; the openable areas are to be checked against the window schedule before issue. Internal doors undercut 10mm above the floor finish (7600mm² for a 760mm door).",
    "Continuous mechanical extract (System 3) to have 4000mm² background ventilators to each habitable room and not fewer than the number of bedrooms plus two; mechanical ventilation with heat recovery (System 4) to have no background ventilators, supply terminals placed to avoid draughts and wet-room air not recirculated; continuous rates not less than 13 litres per second from the kitchen, 8 from each bathroom and utility room and 6 from a WC, with the whole-dwelling rate as above. Every fixed mechanical ventilation system in every flat to be commissioned with the flow rates measured to BS EN 13141-6 or 13141-7, recorded on the Approved Document F commissioning sheet, given to building control within five days of the final test and to the occupier in the Home User Guide."]},
  {c:"Ventilation", t:"Ventilation of Common Areas and Ancillary Spaces", p:[
    "Common corridors and stairs to be ventilated as the smoke control strategy and, where they are enclosed, by natural or mechanical ventilation to Approved Document F Volume 2 to control condensation and odour. Refuse stores to be ventilated to the outside by permanent openings of not less than 0.2m² or by mechanical extract, and plant rooms, cycle stores and bin stores ventilated to the manufacturer's and the local authority's requirements. Car parks below the building are dealt with in the Undercroft and Basement Car Parks note."]},
  {c:"Overheating (Part O)", t:"Limiting Overheating Risk in Flats (Part O)", p:[
    "Every flat is to be shown to comply with Requirement O1, either by the simplified method in Approved Document O Section 1, applied to the worst-case flat for each orientation and to cross-ventilated and single-aspect flats separately, or by dynamic thermal modelling to CIBSE TM59 in Section 2, which is normally required for single-aspect flats in a high-risk location and for any flat where the noise or air quality strategy prevents night-time window opening.",
    "Under the simplified method the glazing area in each orientation is not to exceed the percentage of floor area in Approved Document O Table 1.1, and the free area of openings for removing excess heat, in bedrooms and in the flat as a whole, is to be not less than Table 1.2, both read for the risk location and for whether the flat is cross-ventilated; glazing in a high-risk location is to have external shutters or shading, or glass with a g-value not more than 0.4 and light transmittance not less than 0.7, or an overhang giving a 50 degree altitude cut-off on due-south facades. Openings relied on for night cooling are to be safe to use: where the drop outside is 1.1m or more the opening is to have guarding to 1100mm or be limited to 100mm by a restrictor (Table 3.1), handles are to be within 650mm of the inside face of the wall at the maximum opening, grilles and security screens are not to pass an 8mm gap or an object that a child's finger could enter, and looped blind cords are to have safety devices; noise, pollution and security are to be shown not to prevent the windows being opened at night, otherwise mechanical cooling or a modelled solution is required. The occupier is to be given the Approved Document O information on how the flat is kept cool in the Home User Guide, and the Appendix B checklist completed for building control.",
    "Communal heating pipework and hot water risers passing through the flats and corridors are a significant heat gain and are to be insulated to the standards in Approved Document L and the CIBSE Code of Practice for heat networks, with the corridors ventilated. The compliance report for every flat type is to be submitted with the full plans, and the as-built flats are to match it.",
    "NOTE — Single-aspect south or west facing flats with floor-to-ceiling glazing are the type most likely to fail Part O, and the fix at design stage is a smaller window, external shading or a low g-value glass rather than mechanical cooling.",
    "Protection from falling and entrapment: where a window or door is relied on to provide the free area for cooling and the bottom of its opening is below the guarding height Approved Document K requires, the opening is to be guarded or its travel restricted so that a fall through it is prevented while the free area is still achieved, and any opening that could trap a limb is to be limited or guarded; the restrictors and guards are to be shown on the window schedule and are not to be of a kind the occupant must remove to open the window. Where the strategy depends on openings being usable at night, their security, noise and pollution constraints are to be checked as Approved Document O Section 3 requires and the mitigation revised where they cannot be relied on."]},
  {c:"Condensation (C2)", t:"Interstitial and Surface Condensation", p:[
    "Vapour control layers on the warm side of all insulated framed constructions with laps and penetrations sealed, breather membranes on the cold side, and all roofs either ventilated or constructed as warm roofs. Junctions to be designed to accredited construction details or calculated so the temperature factor is not less than 0.75, with particular attention to slab edges, balcony connections and window heads and sills in framed construction; thermal break connectors to balconies and brick support angles are to be used where the psi value requires them. A condensation risk analysis to BS EN ISO 13788 is to be provided for any construction not covered by an accredited detail."]},
  {c:"Drainage & Refuse", t:"Foul and Surface Water Drainage", p:[
    "Above-ground drainage to BS EN 12056-2 with soil stacks of 100mm minimum ventilated to the open air above the roof or fitted with air admittance valves where the standard permits, branches of 32mm to basins, 40mm to baths, showers and sinks and 100mm to WCs with 75mm seal traps, and stacks enclosed in fire-stopped ducts where they pass through compartment floors with the pipe material and fire stopping as Approved Document B Volume 1 Section 9. Below-ground drainage to BS EN 752 and Approved Document H with inspection chambers at changes of direction and junctions, connection to the public sewer under a Section 106 agreement with the undertaker, and a Section 104 agreement where sewers are to be adopted.",
    "Surface water to be disposed of by infiltration, watercourse or surface water sewer in that order of preference, with SuDS features, attenuation and flow control as the drainage strategy approved by the lead local flood authority, and no surface water connected to the foul sewer. Roof outlets to have overflows, and podium and balcony drainage to be independent of the flats.",
    "Where surface water cannot go to a sewer or a watercourse it is to discharge to soakaways sited not less than 5m from the building and from any boundary, sized on a percolation test to BRE Digest 365 for the roof and paved areas they serve; crated modular soakaways wrapped in a geotextile and rubble-filled pits are both acceptable, each with an inspection point and a silt trap before the inlet, and the ground beneath the car park and refuse areas is to be checked for contamination before infiltration is adopted there."]},
  {c:"Drainage & Refuse", t:"Refuse Storage", p:[
    "Refuse and recycling storage to Approved Document H Section 6 and the local authority's guidance: a store with capacity for the number and type of containers the authority collects, within 30m of every flat entrance door and within 25m of the collection vehicle position, with a hard level path not steeper than 1:12, a door of 1200mm minimum clear width, an impervious washable floor with a trapped gully, ventilation to the outside, and fire separation from the flats of 60 minutes fire resistance with a self-closing fire door. Chutes, where provided, to BS 5906 with a hopper on each floor in a ventilated lobby and a fire-rated cut-off at the base."]},
  {c:"Drainage & Refuse", t:"Drainage — Depths, Chambers, Branch Pipes, Building Over Sewers and Pumped Drainage", p:[
    "Below-ground drains to be laid with not less than 600mm cover under gardens and landscaped areas and 900mm under drives and roads (1200mm for rigid pipes under roads), or protected by a reinforced concrete slab on a compressible layer with 75mm of granular material between the pipe and the slab where the cover is less; bedded on and surrounded by 100mm of pea gravel, with flexible joints and rocker pipes not more than 600mm long each side of a wall or foundation and 50mm clearance in the opening, or the foundation carried down below the drain and the drain sleeved. Inspection chambers at every change of direction or gradient, at junctions and at not more than 45m centres, 450mm diameter to 1.2m deep, with double-sealed bolt-down covers inside the building and vehicle-rated covers in drives; rodding eyes at the head of each run. Drains under the building to be kept as short as possible with access at both ends and tested before the floor is placed, with a 1m wide strip of A142 mesh in the slab over the run and a 150mm concrete surround where the crown is within 300mm of the underside of the slab; no manhole is to be enclosed within a flat.",
    "Above-ground pipework to BS EN 12056-2 with 75mm seal traps and branch lengths not exceeding 1.7m for a 32mm basin waste (3m at 40mm), 3m for a 40mm bath or shower waste (4m at 50mm) and 6m for a 100mm WC branch, beyond which anti-vacuum traps or a ventilated branch are needed; no branch is to connect within 200mm below a WC branch connection, the stack is to have a long-radius bend at its foot, and an air admittance valve to BS EN 12380 may replace an open vent only where at least one stack on the drain remains open to the air and the valve is above the highest spill-over level in an accessible ventilated position. Building over or within 3m of a public sewer, over a manhole, or where the sewer is more than 3m deep or larger than 225mm requires a build-over agreement with the sewerage undertaker before work starts, with a CCTV survey of the sewer before and after and the protective measures in the agreement implemented. Where a basement or ground-floor appliance is below the sewer level, or gravity fall cannot be achieved, a packaged pumping station to BS EN 12056-4 and BS EN 12050 with duplicate pumps, a non-return valve, an alarm and 24 hours' storage in an accessible chamber outside the flats, discharging by a rising main to a gravity manhole; a pumping station serving more than one flat is to be maintainable by the management company and its location shown on the site plan, and a pumped WC or macerator is permitted only where a gravity WC is also available in the flat. All new drains to be tested by air or water in the presence of the Building Control Officer before backfilling and again at completion."]},
  {c:"Water & Sanitary (Part G)", t:"Water Supply, Efficiency and Hot Water Safety", p:[
    "Each flat to be designed to a calculated water consumption of not more than 125 litres per person per day using the calculator in Approved Document G Appendix A, or 110 litres where the planning permission imposes the optional requirement, with the calculation for each flat type submitted at completion. Cold water to be supplied from the mains or from a boosted supply with break tank where the mains pressure is inadequate for the upper floors, with the tank and pump set to the Water Supply (Water Fittings) Regulations 1999 and Legionella control to HSG274.",
    "Hot water storage to Approved Document G3: every cylinder with a thermostat and a non-self-resetting energy cut-out so that the stored water cannot exceed 100°C, capable of being stored at not less than 60°C to control legionella, and marked with the installer, capacity, operating pressure and the location of the discharge; unvented cylinders to BS EN 12897 installed by a person registered with a competent person scheme for unvented hot water, with the temperature and pressure relief valve, expansion vessel, a tundish within 500mm of the valve and the D1 and D2 discharge pipework one size larger than the valve outlet routed to a safe and visible termination with a warning label, and the installation notified to building control. The hot water supplied to every bath is to be limited to not more than 48°C by a thermostatic mixing valve to BS EN 1111 or BS EN 1287 fitted as close to the bath as practicable and set so that it cannot readily be altered by the occupier. Sanitary appliances, WCs and wash hand basins to Approved Document G4 and G5, with a wash hand basin in or adjacent to every room containing a WC, and all fittings and pipework to the Water Supply (Water Fittings) Regulations 1999."]},
  {c:"Services", t:"Heating and Hot Water", p:[
    "Space heating and hot water to be as the SAP calculation and the planning energy strategy: individual heat pumps or electric systems to each flat, or a communal heat network with a central plant room, distribution pipework and a heat interface unit in each flat, in which case the network is to be designed to the CIBSE and ADE Heat Networks Code of Practice CP1 with a maximum flow temperature of 55°C for new systems, all distribution pipework insulated to the Code, heat meters and billing to the Heat Network (Metering and Billing) Regulations, and the network registered where the Heat Networks regulations require. Every flat, whether served by the network through a heat interface unit or by its own system, is to have the controls in Approved Document L Volume 1 Section 5 as the Heating and Hot Water Within Flats note.",
    "NOTE — Under the Future Homes Standard (Approved Document L 2026, in force 24 March 2027) new flats are expected to be heated without a fossil fuel boiler, and a communal gas boiler is unlikely to comply. Where the application will be made or the work will not commence before the transitional dates, design to the 2026 edition now."]},
  {c:"Services", t:"Electrical Installation, Lighting and Emergency Lighting", p:[
    "Electrical installation to BS 7671 and Approved Document P by a registered competent person, with a landlord's supply to the common areas, metering to each flat in a meter cupboard or riser accessible to the supplier, a consumer unit in each flat, RCD protection to every circuit, surge protection, arc fault detection where required, and independent switching to the lighting of each room. Emergency escape lighting to BS 5266-1 in the common escape routes, stairs, lobbies, plant rooms and refuse stores with a three-hour duration and monthly and annual testing recorded. All fixed internal and external light fittings, in the flats and in the common areas, to have a luminous efficacy of not less than 75 light-source lumens per circuit-watt (Approved Document L Volume 1 Section 6; fittings under 5 circuit-watts are excluded), with the common area lighting on presence detection or daylight control and external lighting on a daylight cut-off with presence detection or manual control; downlighters are not to be installed in a separating ceiling other than as a tested fire-rated and acoustic-rated fitting. Sockets, switches and controls at 450mm to 1200mm above floor level."]},
  {c:"Access (Part M)", m4:"1", t:"Category M4(1) — Communal Approach, Entrance, Lifts and Stairs", p:[
    "The flats are designed to Requirement M4(1) of Schedule 1, the category that applies unless the planning permission imposes optional requirement M4(2) or M4(3) for some or all of them (Approved Document M Volume 1, 2015 edition incorporating 2016 amendments, Section 1). Where the permission requires a number of flats to meet M4(2) or M4(3), those flats and the communal parts serving them follow the note for that category instead, and the flats concerned are identified on the drawings.",
    "Communal approach and entrance (Section 1A): the route from the boundary, the parking or the drop-off point to the principal communal entrance as for a private approach — level, gently sloping, ramped or only where unavoidable stepped, not less than 900mm wide with a cross fall not exceeding 1 in 40, ramp flights not longer than 10m at 1:15 or 5m at 1:12 with 1200mm landings, and steps of 75mm to 150mm rise with 280mm goings and a handrail to one side of any flight of three or more risers. The principal communal entrance door with a clear opening width of not less than 775mm (Diagram 1.1), an accessible threshold — level or, where raised, not more than 15mm high in total with the fewest upstands and slopes and any upstand higher than 5mm chamfered, and an entrance floor surface that does not impede a wheelchair.",
    "Communal lifts and stairs (paragraphs 1.10 to 1.12): a passenger lift is the most convenient means between storeys and where one is provided it is suitable for a wheelchair user — a clear landing not less than 1500mm × 1500mm in front of the lift door at every level, a load capacity of not less than 400kg, doors of not less than 800mm clear opening, a car not less than 900mm wide × 1250mm deep internally, tactile storey indication on the landing beside the call button and on or beside the car buttons, a visual signal that the lift is answering a landing call, a dwell time of five seconds before the doors begin to close, a door re-activating device other than a door-edge pressure system that keeps the door fully open for not less than three seconds, visual and audible floor indication where the lift serves more than three storeys, and landing and car controls 900mm to 1200mm above the car floor and not less than 400mm from the front wall (a lift to BS EN 81-70 type 1 satisfies the indication, signalling, dwell and re-activation provisions). Where lift access cannot reasonably be provided, a suitable stair is acceptable. The principal communal stair meets Part K for a general access stair where a flat on an upper floor has no lift access, and for a utility stair where it has."]},
  {c:"Access (Part M)", m4:"1", t:"Category M4(1) — Within the Flat", p:[
    "Principal private entrance (Section 1B): a door with a clear opening width of not less than 775mm measured from the face of the open leaf to the opposing stop (Diagram 1.1 — a standard 826mm leaf up to 44mm thick satisfies this); an accessible threshold — level or, where raised, not more than 15mm high in total with the fewest upstands and slopes and any upstand higher than 5mm chamfered; and, only where a step into the flat is unavoidable, a rise of not more than 150mm aligned with the outside face of the threshold.",
    "Within the entrance storey, or the principal storey where the entrance storey has no habitable room: every door to a habitable room and to the room containing the WC with a clear opening width from Table 1.1 — 750mm or wider where approached head-on from a corridor of 900mm; and where the approach is not head-on, 750mm off a 1200mm corridor, 775mm off a 1050mm corridor or 800mm off a 900mm corridor. A localised obstruction such as a radiator is not to sit opposite or close to a doorway, is not longer than 2m, and does not reduce the corridor below 750mm at any point. A stepped change of level within the entrance storey is avoided; where one is unavoidable it complies with Part K.",
    "A room containing a WC — a cloakroom or a bathroom — on the entrance storey, or on the principal storey where the entrance storey has no habitable room, with the clear access zone of Diagram 1.3: 750mm clear in front of the pan for a frontal transfer, or 750mm clear to the side for an oblique transfer, with the pan centre line not less than 450mm (500mm preferred) from the adjoining wall; the basin positioned so that it does not impede the zone; and the door opening outwards with a clear opening width from Table 1.1.",
    "Services and controls: switches and sockets serving habitable rooms — light switches, power sockets, door bells, entry phones, TV aerial and telephone outlets — with their centre line 450mm to 1200mm above floor level (Diagram 1.5), and the consumer unit mounted with its switches 1350mm to 1450mm above floor level."]},
  {c:"Access (Part M)", m4:"2", t:"Category M4(2) — Communal Approach, Entrance, Lifts and Stairs", p:[
    "The planning permission imposes optional requirement M4(2) on the flats covered by this specification, applying in place of M4(1) (Approved Document M Volume 1, 2015 edition incorporating 2016 amendments, Section 2); the flats concerned are identified on the drawings, and the communal parts serving them meet the Category 2 provisions. Clear zones and turning spaces are demonstrated on the drawings with furniture of the sizes in Appendix D.",
    "Communal approach (Section 2A): step-free from the boundary, the parking and the drop-off point to the principal communal entrance and to every communal facility the flat uses — including refuse and recycling stores, but not plant rooms unless occupants need regular access — irrespective of the storey the flat is on; communal parts of the route not less than 1200mm clear, 1050mm at a localised obstruction that is not opposite or close to a doorway or a change of direction and is not longer than 2m; a firm, even and slip-resistant surface; every gate 850mm clear with a 300mm nib to its leading edge; ramps between 1:20 and 1:12 limited by Diagram 2.1 (10m at 1:20 to 2m at 1:12), communal flights not less than 1200mm clear with landings not less than 1200mm long clear of any door swing; and where a communal ramp rises 300mm or more, an additional stepped route with uniform risers of 150mm to 170mm, goings of 280mm to 425mm, not more than 1800mm rise in a flight, 900mm clear width, 900mm landings and a grippable handrail 850mm to 1000mm above the pitch line extending 300mm beyond the nosings, to both sides where the flight is wider than 1000mm. Communal parking: at least one standard bay close to the communal entrance of each core — or to the lift core where the parking is internal — with a 900mm clear access zone to one side and a dropped kerb, step-free to the entrance. A drop-off point, where provided, close to the principal communal entrance, level or where unavoidable gently sloping, with a dropped kerb not less than 1000mm wide, reasonably flush and not steeper than 1:12.",
    "Principal communal entrance (paragraph 2.14): a level landing not less than 1500mm × 1500mm outside the door clear of its swing, covered for not less than 1200mm wide × 900mm deep; fully diffused lighting on a dusk-to-dawn timer or a motion detector; a door or gate with a clear opening of not less than 850mm (Diagram 2.2), the leading leaf of a double door providing the full width; a 300mm nib to the leading edge maintained for 1200mm beyond it; a reveal on the leading side not deeper than 200mm; an accessible threshold — level or, where raised, not more than 15mm high in total with the fewest upstands and slopes and any upstand higher than 5mm chamfered; where there is a lobby or porch, the doors 1500mm apart with 1500mm between door swings; an entrance floor that does not impede a wheelchair; and door entry controls 900mm to 1000mm above finished ground level and not less than 300mm from a projecting corner. Every other communal door or gate on the approach route meets the same width, nib, reveal, threshold, lobby, surface and control provisions. Communal lifts (paragraph 2.16): a clear landing not less than 1500mm × 1500mm in front of the lift door at every level, a lift to BS EN 81-70 type 2 or equivalent, a car not less than 1100mm wide × 1400mm deep internally, doors of 800mm clear opening, landing and car controls 900mm to 1200mm above the car floor and not less than 400mm from the front wall, and a dwell time of five seconds before the doors begin to close. The principal communal stair meets Part K for a general access stair."]},
  {c:"Access (Part M)", m4:"2", t:"Category M4(2) — Within the Flat", p:[
    "Principal private entrance (Section 2B): a level external landing not less than 1200mm × 1200mm, covered for not less than 900mm wide × 600mm deep; fully diffused lighting switched by a dusk-to-dawn timer or a motion detector; a door with a clear opening width of not less than 850mm (Diagram 2.2 — the leading leaf of a double door providing the full width); a 300mm nib to the leading edge of the door with the extra width maintained for 1200mm beyond it; a reveal on the leading side not deeper than 200mm; an accessible threshold — level or, where raised, not more than 15mm high in total with the fewest upstands and slopes and any upstand higher than 5mm chamfered; and where there is a lobby or porch, the doors 1500mm apart with 1500mm between door swings. Every other external door — to a garden, balcony, terrace, garage, carport, conservatory or store — meets the same door width, nib, reveal, threshold and lobby provisions.",
    "Halls and landings not less than 900mm clear; a localised obstruction such as a radiator not opposite or close to a doorway or a change of direction, not longer than 2m and not reducing the width below 750mm; every internal door with the clear opening width of Table 2.1 — 750mm off a 900mm corridor approached head-on, and where the approach is not head-on 750mm off 1200mm, 775mm off 1050mm or 800mm off 900mm; and a 300mm nib to the leading edge of every inward-opening door in the entrance storey (each leaf of a double door 300mm or wider gives the nib; a standard 826mm leaf up to 44mm thick gives 775mm clear). Cupboards not large enough to enter, and en-suites additional to the sanitary provision below, are exempt.",
    "Access to every room and facility in the entrance storey is step-free and changes of level within every other storey of a maisonette are avoided where possible. The stair from the entrance storey to the storey above — or below, where that storey contains the bathroom — is not less than 850mm clear measured 450mm above the pitch line ignoring the newel post, so that a stair-lift can be fitted, and every stair meets Part K for a private stair.",
    "Living: a living area — a living room, a dining room or a combined kitchen and dining room — within the entrance storey; not less than 1200mm clear in front of and between all kitchen units and appliances; and glazing to the principal window of the principal living area starting not more than 850mm above floor level, or at the minimum height Part K requires for guarding. Bedrooms: every bedroom with a 750mm clear route from the door to the window; the principal double bedroom with a 750mm clear zone to both sides and the foot of the bed, every other double bedroom to one side and the foot, and single and twin bedrooms to one side of each bed, shown on dimensioned layouts (Diagram 2.4) with bedside furniture permitted only in the zone at the bedhead.",
    "Sanitary accommodation: the walls, ducts and boxings of the cloakroom, bathroom and shower room built to carry grab rails, seats and other adaptations imposing 1.5kN/m² — additional sanitary rooms need not be strengthened, and localised strengthening may still be needed for a fitting that imposes a high point load. A room on the entrance storey with a WC and basin, its door opening outwards: in a two- or three-storey flat with one or two bedrooms the WC and its access zone follow Diagram 1.3 with the basin clear of the zone; with three or more bedrooms the room also has an installed level access shower, or the floor and drainage laid out so that one can be fitted later without structural alteration, and the shower, WC and basin zones follow Diagram 2.5 (the 1500mm turning circle may overlap the shower; a hand-rinse basin may encroach 200mm and a wash basin 300mm into the WC zone; radiators and towel rails clear of every zone). Where a Category 2 bathroom and a cloakroom share a storey the cloakroom may follow Diagram 1.3. A bathroom with a WC, basin and bath on the same storey as the principal bedroom, laid out to Diagram 2.5, with provision for a future level access shower where none is provided elsewhere; stack and drainage positions shown clear of the access zones.",
    "Services and controls: the consumer unit with its switches 1350mm to 1450mm above floor level; switches, sockets, stopcocks and controls with their centre line 450mm to 1200mm above floor level and not less than 300mm from an inside corner; the handle to at least one window in the principal living area 450mm to 1200mm above floor level and the handles to all other windows 450mm to 1400mm, unless a remote opening device within those heights is fitted; and the boiler timer and thermostat 900mm to 1200mm above floor level on the boiler, or separate wired or wireless controllers within the same range. Radiator and cooker hood controls are exempt."]},
  {c:"Access (Part M)", m4:"3", t:"Category M4(3) — Communal Approach, Entrance, Lifts and Stairs", p:[
    "The planning permission imposes optional requirement M4(3) on the flats covered by this specification, applying in place of M4(1) (Approved Document M Volume 1, 2015 edition incorporating 2016 amendments, Section 3); the flats concerned are identified on the drawings and the communal parts serving them meet the Category 3 provisions. Each is a wheelchair adaptable dwelling under M4(3)(2)(a) unless the permission specifies a wheelchair accessible dwelling under M4(3)(2)(b), which a local planning authority may require only where it is responsible for allocating or nominating the occupant; the further provisions for a wheelchair accessible dwelling are stated below where they differ. Furnished plan layouts at not less than 1:100 showing the access zones, turning circles and the furniture of Appendix D accompany the application.",
    "Communal approach (Section 3A): step-free from the boundary, the parking, the drop-off point and any mobility scooter store to the principal communal entrance and to every communal facility the flat uses, irrespective of the storey the flat is on; not less than 1200mm clear; a localised obstruction not opposite or close to a doorway or a change of direction and not longer than 2m; a level passing and turning space not less than 1500mm × 1500mm at each end of the route and at intervals of not more than 10m; a firm, even and slip-resistant surface; fully diffused lighting to the external parts on a dusk-to-dawn timer or a motion detector; every gate 850mm clear with a 300mm nib to the leading edge and a 200mm nib to the following edge; ramps between 1:20 and 1:15 limited by Diagram 3.1 (10m at 1:20 to 5m at 1:15), flights not less than 1200mm clear, every landing level and 1200mm clear of any door swing; and where a communal ramp rises 300mm or more an additional stepped route as for Category 2 with no single steps. Communal parking: a standard bay with 1200mm clear to both sides, a side zone shared by two bays where the layout allows, level, with 2200mm clear headroom and a suitable surface. A drop-off point, where provided, close to the communal entrance of the core containing the flat, level, with a dropped kerb not less than 1000mm wide, reasonably flush and not steeper than 1:15.",
    "Principal communal entrance (paragraph 3.14): a level landing not less than 1500mm × 1500mm outside the entrance, covered for not less than 1200mm × 1200mm; fully diffused lighting on a dusk-to-dawn timer or a motion detector; a 1500mm clear turning circle inside the entrance behind the closed door; a door or gate with a clear opening of not less than 850mm (Diagram 3.2), the main leaf of a double door providing the full width; a 300mm nib to the leading edge and a 200mm nib to the following edge, each maintained for 1800mm beyond the door; the door set reasonably centrally in the wall with the reveal on the leading face not deeper than 200mm; an accessible threshold — level or, where raised, not more than 15mm high in total with the fewest upstands and slopes and any upstand higher than 5mm chamfered; where there is a lobby or porch, the doors 1500mm apart with 1500mm clear between door swings; power-assisted opening where the opening force exceeds 30N between 0° and 30° or 22.5N between 30° and 60° of the opening cycle; an entrance floor that does not impede a wheelchair; and door entry controls 900mm to 1000mm above finished ground level and not less than 300mm from a projecting corner. Every other communal door or gate on the approach route meets the same provisions. Communal lifts (paragraph 3.16): a clear landing not less than 1500mm × 1500mm in front of the lift door at every level, a lift to BS EN 81-70 type 2 or equivalent, a car not less than 1100mm wide × 1400mm deep, doors of 800mm clear opening, controls 900mm to 1200mm above the car floor and not less than 400mm from the front wall, and a dwell time of five seconds. The principal communal stair meets Part K for a general access stair."]},
  {c:"Access (Part M)", m4:"3", t:"Category M4(3) — Within the Flat", p:[
    "Principal private entrance (Section 3B, Diagram 3.3): a level external landing not less than 1500mm × 1500mm clear of the door swing, covered for not less than 1200mm × 1200mm; fully diffused lighting switched by a dusk-to-dawn timer or a motion detector; a 1500mm clear turning circle inside the entrance in front of the closed door; a door with a clear opening width of not less than 850mm (Diagram 3.2), a 300mm nib to the leading edge with the extra width maintained for 1800mm beyond it, a 150mm nib on the hinge side to take a letter-box cage, and for a double door a 200mm nib to the following edge maintained for 1500mm; the door set reasonably centrally in the wall thickness with the reveal on the leading face not deeper than 200mm; an accessible threshold — level or, where raised, not more than 15mm high in total with the fewest upstands and slopes and any upstand higher than 5mm chamfered; where there is a lobby or porch, the doors 1500mm apart with 1500mm between door swings; door entry controls, where provided, 900mm to 1000mm above finished ground level and 300mm from any external return corner; and a fused spur on the hinge side for a future powered door opener. Every other external door — to a garden, balcony, terrace, garage, carport, conservatory or store — has the same 850mm clear width, reveal, threshold, lobby and entry-control provisions with a 300mm nib to its leading edge maintained for 1800mm.",
    "Halls, approaches and landings not less than 1050mm clear, and 1200mm where the approach to a door is not head-on (Diagram 3.4); a localised obstruction not longer than 2m and not opposite or close to a doorway or a change of direction; every internal door 850mm clear whichever way it is approached (Diagram 3.2), with a 300mm nib to the leading edge and a 200mm nib to the following edge (each leaf of a double door 300mm or wider gives the nibs); and where an outward-opening door sits near a corner with another door on the return wall within 800mm, its leading edge not less than 800mm from the corner unless a 1500mm turning circle is provided outside it (Diagram 3.5). Cupboards not large enough to enter, and en-suites additional to the sanitary provision below, are exempt. A wheelchair storage and transfer space not less than 1100mm deep × 1700mm wide on the entrance storey, preferably close to the entrance, entered from a space not less than 1200mm wide and with a power socket for charging (Diagram 3.6); in a wheelchair adaptable dwelling the space may serve as general storage with doors fitted, provided it can be brought into use without alteration to structure or services and is additional to the minimum storage that follows. General built-in storage of not less than 1.5m² for a one-bedroom flat, 2.0m² for two bedrooms, 2.5m² for three, 3.0m² for four, 3.5m² for five and 4.0m² for six (Table 3.1), counting floor with headroom between 900mm and 1500mm at half its area, headroom below 900mm not at all, and the whole area under a stair as 1m².",
    "Where the flat has more than one storey, a through-floor lift or the provision for one (paragraphs 3.27 to 3.29). Wheelchair adaptable: a future liftway not less than 1100mm wide × 1650mm long internally linking the circulation areas at every floor level; any floor, wall or door built to use the space meanwhile removable without structural alteration, and the liftway enclosure walls capable of being put in later without structural work; drawings showing how the lift could be fitted; and the space not counted towards the minimum living, dining and kitchen area. Wheelchair accessible: a through-floor lift or lifting platform installed and commissioned, with a continuous liftway not less than 1100mm × 1650mm entered from the same narrow end at every level, a 1500mm turning circle clear of the liftway door when open at 90° on every level (Diagram 3.7), a power socket close to the liftway, the end opposite the entry against a wall at every level, and power-operated doors — in a two-storey dwelling typically a home lift to BS 5900 or a lifting platform to BS EN 81-41, a platform possibly needing a larger liftway and a three-phase supply. Access to every room and facility in the entrance storey is step-free and there is no change of level within any other storey; the stair from the entrance storey to the storey above or below, and any stair within that storey, is not less than 850mm clear measured 450mm above the pitch line ignoring the newel post, with a power socket close to its foot or head for a future stair-lift, and every stair meets Part K for a private stair.",
    "Living (paragraphs 3.31 to 3.34): the principal living area within the entrance storey; the combined living, dining and kitchen floor area not less than 25m² for two bedspaces, 27m² for three, 29m² for four, 31m² for five, 33m² for six, 35m² for seven and 37m² for eight (Table 3.2); and glazing to its principal window starting not more than 850mm above floor level, or at the minimum Part K guarding height. The kitchen and the principal eating area in the same room or connected, within the entrance storey, with a 1500mm clear zone in front of and between all units and appliances. Wheelchair adaptable: a worktop length including fittings and appliances of not less than 4330mm for two bedspaces, 4730mm for three or four, 5630mm for five and 6730mm for six to eight (Table 3.3), with drawings showing how the kitchen could later meet the wheelchair accessible provisions without moving structural walls, stacks or concealed drainage. Wheelchair accessible (Diagram 3.8): a worktop length of not less than 6130mm for two bedspaces, 6530mm for three or four, 7430mm for five and 8530mm for six to eight (Table 3.4), including a continuous 2200mm section carrying the sink, drainer and hob that is height adjustable or capable of being refixed at alternative heights, with no fixed appliance beneath it and clear open leg space capable of 700mm clearance; a sink not deeper than 150mm insulated on its underside; lever taps; a space for a built-in oven with its centre line 800mm to 900mm above floor level and a pull-out shelf beneath; not less than 400mm of worktop to one side of the oven and of any fridge or freezer taller than the worktop; isolation valves and flexible tails to the sink supply; and drainage that is flexible, or fixed but easily adapted to worktop heights of 700mm to 950mm.",
    "Bedrooms (paragraph 3.35): one bedroom close to the accessible bathroom and every bedroom reachable by a wheelchair user; every bedroom with a 750mm clear route from the door to the window, a 1200mm × 1200mm manoeuvring space inside the door clear of the bed and the closed door, and a ceiling structure able to carry an overhead hoist of 200kg, with localised strengthening added at the hoist when one is fitted; the principal double bedroom on the entrance storey or the storey above or below it, not less than 13.5m² and 3m wide clear of obstructions, with a 1000mm clear zone to both sides and the foot of the bed and in front of all furniture and a 1200mm × 1200mm manoeuvring space on both sides of the bed (Diagram 3.9); every other double or twin bedroom not less than 12.5m² and 3m wide with a 1000mm zone to one side and the foot of the bed and in front of furniture; and every single bedroom not less than 8.5m² and 2.4m wide with a 1000mm zone to one side of the bed and in front of furniture. Furniture may encroach 600mm into a zone at the bedhead end only. For counting bedspaces a bedroom of 8.5m² up to 12.5m² is one bedspace and one of 12.5m² or more is two.",
    "Sanitary accommodation (paragraphs 3.36 to 3.43 and Table 3.5): a flat with four or more bedspaces has two WCs in separate rooms; every room with an installed level access shower is built as a wet room; the walls, ducts and boxings to every cloakroom, bathroom and shower room carry adaptations imposing 1.5kN/m²; the ceiling structure to those rooms carries a 200kg hoist; and stacks and soil pipes are kept away from the WC except where there is no practical alternative, and then on the wall side. On the entrance storey a wet room — a cloakroom or a bathroom — with a WC, basin and installed level access shower and its door opening outwards: wheelchair adaptable to Diagram 3.10 (a 1500mm turning circle that may overlap the shower; a shower of 1200mm × 1200mm in a bathroom or 1000mm × 1000mm in a cloakroom; the pan centre line 450mm to 500mm from the wall; a hand-rinse basin encroaching not more than 200mm and a wash basin 300mm into the WC zone) with drawings showing how it could be adapted to the accessible layout; wheelchair accessible to Diagram 3.11 (a shower of 1200mm × 1200mm, or 1000mm × 1200mm where it can be widened when a bath is removed; the turning circle overlapping the shower by not more than 500mm; a 1000mm × 1000mm × 100mm zone beside the WC kept clear for grab rails; 800mm between the pan centre line and the shower edge in a bathroom; and 400mm to 600mm clear beneath the basin). Where a bathroom and a cloakroom share a storey, the cloakroom WC and basin may follow Diagram 3.13, the basin encroaching not more than 200mm into the WC zone. The bathroom with the installed level access shower is on the same storey as the principal bedroom; with up to four bedspaces it holds a WC, basin and level access shower with the potential for a bath to be installed over the shower, or a bath elsewhere on that storey, and a wheelchair accessible dwelling with five or more bedspaces has both a usable bath and an installed level access shower, in one bathroom or in two on that storey (Diagram 3.17); the shower sits in a corner so that a seat can be fitted to one wall with the controls on the adjacent wall, and the bathroom has a 1500mm turning circle. In a wheelchair accessible dwelling the WC flush is a lever at the front of the cistern on the transfer side, the pan is not less than 400mm high, and basins and sinks are wall hung with the rim 770mm to 850mm above the floor and the space beneath kept as clear as the trap allows, ideally 400mm to 600mm above the floor.",
    "Services and controls (paragraph 3.44): the consumer unit with its switches 1350mm to 1450mm above floor level; switches, sockets, stopcocks and controls, radiator controls excepted, with their centre line 700mm to 1000mm above floor level, not less than 700mm from an inside corner and not behind appliances; in a wheelchair accessible dwelling, appliance isolators in the same band and radiator controls 450mm to 1000mm above floor level; the handle to at least one window in the principal living area 700mm to 1000mm above floor level and every other window handle 450mm to 1200mm, unless a remote opening device within those heights is fitted; door handles, locks, latches and catches easy to grip and 850mm to 1000mm above floor level; light switches on individual plates unless wide rocker or full-plate fittings are used, and the switches of double sockets at the outer ends of the plate; a door entry phone with remote door release in the main living space and the principal bedroom; provision in the principal bedroom — blank plates, conduit and draw wires — for future bedhead controls comprising a two-way light switch, telephone and broadband, TV aerial and power sockets and the entry phone, grouped at the head of the bed; a power socket and a telephone point together in the main living space; taps and bathroom controls that a person with limited grip can work with one hand; and the boiler timer and thermostat 900mm to 1200mm above floor level on the boiler, or separate controllers within the same range.",
    "Private outdoor space (paragraph 3.45) — garden, balcony or roof terrace: not less than 1500mm clear width with a level 1500mm turning circle free of any door swing; a level or gently sloping path not less than 1050mm wide to every private refuse, recycling, cycle or other store, ending in a 1500mm turning circle; every gate 850mm clear with a 300mm nib to the leading edge and a 200mm nib to the following edge; the door to every external store integral with or connected to the flat 850mm clear; and all paved areas with a firm, even and slip-resistant surface."]},
  {c:"Security (Part Q)", t:"Secure Doors and Windows", p:[
    "The communal entrance door, every flat entrance door, and all easily accessible windows and doors, being any at ground level, at basement level, or within 2m of an accessible flat roof, balcony, podium or climbable feature, to be secure doorsets and windows tested to PAS 24:2016 or an equivalent standard. Flat entrance doors within a common area are to meet both PAS 24 and the fire door standard as a single tested doorset; a door that carries a fire certificate and a security certificate from separate tests on different constructions is not acceptable. Communal entrance doors to have an access control system and a door closer, with the door entry panel accessible and the lock releasing on fire alarm activation where the fire strategy requires it."]},
  {c:"EV Charging & Broadband (Parts S & R)", t:"Electric Vehicle Charging", p:[
    "Where the development has associated parking, a charge point of not less than 7 kW with a Type 2 untethered socket and smart functionality is to be installed for every parking space associated with a flat, or, where the connection cost exceeds the £3,600 per charge point threshold, at as many spaces as can be provided within that cost with cable routes to the rest, all to Approved Document S, with the supply capacity agreed with the distribution network operator and load management provided where the capacity is shared. Charging points in a covered or basement car park are to be positioned and protected as the fire strategy requires."]},
  {c:"EV Charging & Broadband (Parts S & R)", t:"Gigabit-Ready Broadband", p:[
    "In-building physical infrastructure to Approved Document R Volume 1: a common access point at the boundary, risers and ducts to every flat with a termination point inside each flat and drawstrings in the ducts, and a gigabit-ready connection where the cost does not exceed £2,000 per flat, otherwise the next fastest connection available within that cost. The routes and the access point are to be shown on the drawings and the risers fire stopped at every compartment floor."]},
  {c:"Conservation of Fuel & Power", t:"Energy Performance Targets", p:[
    "Each flat is to comply with Approved Document L Volume 1 2021 by achieving a Dwelling Emission Rate, Dwelling Primary Energy Rate and Dwelling Fabric Energy Efficiency rate no worse than the target rates for its notional dwelling, calculated by SAP 10.2, with each element no worse than the limiting values in Table 4.1 (walls 0.26, party walls 0.20, floors 0.18, roofs 0.16, windows and doors 1.6, rooflights 2.2 W/m²K, air permeability 8 m³/(h·m²)), and the block as a whole demonstrated compliant where a communal system serves it. Design-stage SAPs for every flat type with predicted EPCs to be submitted with the full plans, and as-built SAPs, BREL reports and EPCs for every flat at completion, with the photographic evidence of each junction and service item taken before it is covered.",
    "Thermal bridging at every junction including the slab edges, balcony connections, brick support angles and window positions to be calculated using accredited construction details, manufacturer's psi values or numerical modelling, and the details on site to match. Party walls between flats to be fully filled and edge sealed so that a U-value of zero is entered in SAP; an unfilled cavity party wall is entered at 0.20 where edge sealed and 0.50 where not, and will normally fail the fabric target.",
    "NOTE — Approved Document L Volume 1 2026 (the Future Homes Standard) comes into force on 24 March 2027 with a transitional period to 24 March 2028 for buildings whose initial notice or full plans were given before that date and where work on the building has commenced. Confirm the edition that applies before the SAPs are run, and where the block will not commence before March 2028 design to the 2026 edition now."]},
  {c:"Conservation of Fuel & Power", t:"High-Efficiency Alternative Systems", p:[
    "Under Regulation 25A the technical, environmental and economic feasibility of high-efficiency alternative systems — decentralised renewable supply, cogeneration, district or block heating and cooling, and heat pumps — is to be considered and documented before work starts and the analysis made available to building control on request, with a statement on the initial notice or full plans that it has been carried out. For a block of flats the comparison between individual heat pumps, a communal heat network with a central heat pump or CHP plant, and connection to any existing district network is the analysis expected, and the planning energy strategy normally records it."]},
  {c:"Conservation of Fuel & Power", t:"Airtightness and Pressure Testing", p:[
    "Every flat is to be pressure tested at completion by a registered tester; Approved Document L Volume 1 2021 no longer allows sample testing of dwellings. The air barrier is to be identified on the drawings and continuous around each flat, including at the separating walls and floors, the riser and duct penetrations and the flat entrance door, and the ventilation system is to be the one consistent with the design air permeability."]},
  {c:"Extra Notes & External Works", t:"Balconies, Chimneys and Water Recovery", p:[
    "Balconies and roof terraces to have guarding of not less than 1100mm to Approved Document K designed for the loads in BS EN 1991-1-1, not climbable and not passing a 100mm sphere, as a metal balustrade with balusters at not more than 100mm clear or a laminated toughened glass system to BS 6180 with the manufacturer's structural calculation; balcony materials as the External Walls, Balconies and Boundaries note, with the balcony drainage independent of the flats and a thermal break at the connection to the slab. Chimneys and flues are not normally provided in flats; where a stove or open fire is proposed it is to comply with Approved Document J with a lined flue, hearth, air supply, carbon monoxide alarm and notice plate, and the flue route through the flats above is to be a protected shaft. Rainwater harvesting to BS EN 16941-1 and greywater recovery to BS 8525-1 may be specified where the SAP or the planning permission relies on them, with Category 5 backflow protection to any non-potable supply and the maintenance regime handed to the management company."]},
  {c:"Renewable Energy", t:"Renewable and Low Carbon Technology", p:[
    "Photovoltaic arrays, where specified in the SAP or the planning energy strategy, to be installed by an MCS-certificated installer on the roof with the structure checked for load and wind uplift, the roof waterproofing protected, isolators and metering in a plant space accessible without crossing the waterproofing unprotected, and the output allocated to the landlord's supply or to the flats as the energy strategy. Batteries, where installed, to be in a fire-separated and ventilated plant room. All commissioning and MCS certificates to be included in the handover information.",
    "Solar thermal collectors with a twin-coil cylinder or a communal pre-heat store, an expansion vessel and a high-limit thermostat; air source heat pumps to MCS MIS 3005 on the roof or in a plant enclosure sited to respect the MCS 020 noise limit at the nearest habitable window, with the condensate drained and the units accessible for maintenance without crossing the waterproofing unprotected; ground source heat pumps with vertical boreholes to the specialist's design where the site allows; and waste water heat recovery units on the shower drains to the SAP Appendix Q listing. Wind turbines are not appropriate on a residential block. Every renewable system is to be entered in the SAP as installed and covered by an MCS certificate.",
    "Waste water heat recovery: where the SAP assessment relies on it, or the client wants it, a waste water heat recovery system is to be fitted to the shower waste — a vertical or horizontal heat exchanger that passes the warm drain water past the incoming cold feed to the shower mixer, the combination boiler or the cylinder — as a product listed in the SAP Product Characteristics Database so that its saving can be claimed, installed with the connections, falls and access for cleaning the manufacturer requires, shown on the drainage drawings, and recorded in the as-built SAP and in the information handed to the occupier."]},
 ]};
